const rtdal004135Source0001 = `plot_tiles <- function(x, adjust = FALSE, add = FALSE, ...) {
  if (!inherits(x, "SpatRaster")) {
    stop(paste0("x should be a SpatRaster"), call. = FALSE)
  }
  ops <- list(...)
  ops$x <- x
  ops$add <- add
  # Default opts
  ops$maxcell <- ifelse(is.null(ops$maxcell), Inf, ops$maxcell)
  ops$bgalpha <- ifelse(is.null(ops$bgalpha), 0, ops$bgalpha)
  ops$smooth <- ifelse(is.null(ops$smooth), TRUE, ops$smooth)


  # Add margins if the raster is smaller than the device
  # Zoom-in if the raster is larger than the device
  if (adjust == TRUE && add == FALSE) {
    if (terra::is.lonlat(ops$x)) {
      message(paste0(
        "The 'adjust' feature does not work with",
        " an unprojected (lon/lat) raster."
      ))
    } else {
      tsp <- dim(ops$x)[2:1]
      dsp <- dev.size("px")
      dsi <- dev.size("in")
      dd <- ((dsp - tsp) / 2) / (dsp / dsi)
      dd <- c(dd[2:1], dd[2:1]) / 0.2
      if (min(dd) >= 0) {
        ops$mar <- dd
      } else {
        et <- terra::ext(ops$x)
        rt <- terra::res(ops$x)[1]
        wp <- (tsp[1] - dsp[1]) / 2
        hp <- (tsp[2] - dsp[2]) / 2
        et[1:4] <- c(
          et[1] + wp * rt, et[2] - wp * rt,
          et[3] + hp * rt, et[4] - hp * rt
        )
        ops$ext <- et
      }
      ops$smooth <- FALSE
    }
  }
  do.call(terra::plotRGB, ops)
}`

