const rtdal004228Source0006 = `.def.unpacked <- .def.packed <- function(x, which, ...) {
    r <- .Call(BunchKaufman_expand, x, .PACKED)
    b <- length(r) - 1L
    switch(which,
           "DU" =, "DL" = {
               if(!endsWith(which, x@uplo))
                   stop(gettextf("%s=\"%s\" invalid for %s@uplo=\"%s\"",
                                 "which", which, "x", x@uplo),
                        domain = NA)
               r[[b + 1L]]
           },
           "U" =, "U." =, "L" =, "L." = {
               if(!startsWith(which, x@uplo))
                   stop(gettextf("%s=\"%s\" invalid for %s@uplo=\"%s\"",
                                 "which", which, "x", x@uplo),
                        domain = NA)
               if(b > 0L) {
                   m <- r[[b]]
                   if(b > 1L)
                       for(i in (b - 1L):1L)
                           m <- r[[i]] %*% m
                   if(endsWith(which, ".")) t(m) else m
               } else {
                   m <- new("ddiMatrix")
                   m@Dim <- x@Dim
                   m@diag <- "U"
                   m
               }
           },
           stop(gettextf("'%s' is not \"%1$s\", \"D%1$s\", or \"%1$s.\"",
                         "which", x@uplo),
                domain = NA))
}`

const rtdal004228Source0007 = `body(.def.unpacked) <-
    do.call(substitute, list(body(.def.unpacked), list(.PACKED = FALSE)))`

const rtdal004228Source0008 = `body(.def.packed) <-
    do.call(substitute, list(body(.def.packed  ), list(.PACKED =  TRUE)))`

const rtdal004228Source0012 = `.def.unpacked <- .def.packed <- function(x, complete = FALSE, ...) {
    r <- .Call(BunchKaufman_expand, x, .PACKED)
    b <- length(r) - 1L
    if(complete) {
        if(b > 0L)
            r <- c(r, lapply(r[b:1L], t))
    } else {
        if(b > 0L) {
            m <- r[[b]]
            if(b > 1L)
                for(i in (b - 1L):1L)
                    m <- r[[i]] %*% m
            r <- list(m, r[[b + 1L]], t(m))
        } else {
            m <- new("ddiMatrix")
            m@Dim <- x@Dim
            m@diag <- "U"
            r <- list(m, r[[1L]], m)
        }
        names(r) <- if(x@uplo == "U") c("U", "DU", "U.") else c("L", "DL", "L.")
    }
    dn <- x@Dimnames
    if(length(r) == 1L)
        r[[1L]]@Dimnames <- dn
    else {
        r[[1L]]@Dimnames <- c(dn[1L], list(NULL))
        r[[length(r)]]@Dimnames <- c(list(NULL), dn[2L])
    }
    r
}`

