const rtdal004240Source0002 = `validDimGetsValue <- function(value, mn) {
    if(mode(value) != "numeric")
        gettextf("assigned dimensions are not of type \"%s\" or \"%s\"",
                 "integer", "double")
    else if(length(value) != 2L)
        gettextf("assigned dimensions do not have length %d", 2L)
    else if(anyNA(value))
        gettext("assigned dimensions are NA")
    else if(any(value < 0L))
        gettext("assigned dimensions are negative")
    else if(is.double(value) && any(trunc(value) > .Machine$integer.max))
        gettextf("assigned dimensions exceed %s", "2^31-1")
    else if((p <- prod(value)) != mn)
        gettextf("assigned dimensions [product %.0f] do not match object length [%.0f]",
                 p, as.double(mn))
    else TRUE
}`

const rtdal004240Source0005 = `fixupDN.if.valid <- function(dn, dim) {
    if(is.character(s <- validDim(dim)) || is.character(s <- validDN(dn, dim)))
        stop(s, domain = NA)
    fixupDN(dn)
}`

const rtdal004240Source0007 = "symmetrizeDN <- function(x) {\n    if(isS4(x)) # assuming is(x, \"Matrix\")\n        `dimnames<-`(x, symDN(x@Dimnames))\n    else if(!is.null(dn <- dimnames(x))) # assuming list of length 2\n        `dimnames<-`(x, symDN(dn))\n    else x\n}"

const rtdal004240Source0009 = `is.null.DN <- function(dn) {
    if(is.null(dn))
        return(TRUE)
    if(!is.null(names(dn)))
        names(dn) <- NULL
    ch0 <- character(0L)
    identical(dn, list(NULL, NULL)) ||
    identical(dn, list( ch0, NULL)) ||
    identical(dn, list(NULL,  ch0)) ||
    identical(dn, list( ch0,  ch0))
}`

const rtdal004240Source0012 = `setMethod("dim<-", c(x = "denseMatrix"),
          function(x, value) {
              if(is.character(s <- validDimGetsValue(value, prod(d <- x@Dim))))
                 stop(s, domain = NA)
              value <- as.integer(value)
              if(all(value == d))
                  return(x)
              r <- .M2gen(x)
              r@Dim <- value
              if(length(r@factors))
                  r@factors <- list()
              r
          })`

const rtdal004240Source0013 = `setMethod("dim<-", c(x = "sparseMatrix"),
          function(x, value) {
              if(is.character(s <- validDimGetsValue(value, prod(d <- x@Dim))))
                 stop(s, domain = NA)
              value <- as.integer(value)
              if(all(value == d))
                  return(x)
              r <- spV2M(.M2V(x), nrow = value[1L], ncol = value[2L])
              switch(.M.repr(x), "C" = .M2C(r), "R" = .M2R(r), r)
          })`

const rtdal004240Source0014 = `setMethod("dim<-", c(x = "sparseVector"),
          function(x, value) {
              if(is.character(s <- validDimGetsValue(value, length(x))))
                 stop(s, domain = NA)
              value <- as.integer(value)
              spV2M(x, nrow = value[1L], ncol = value[2L])
          })`

const rtdal004240Source0015 = `setMethod("length", c(x = "Matrix"),
          function(x)
              if((r <- prod(x@Dim)) > .Machine$integer.max)
                  r
              else as.integer(r))`

const rtdal004240Source0016 = `setMethod("length", c(x = "MatrixFactorization"),
          function(x)
              if((r <- prod(x@Dim)) > .Machine$integer.max)
                  r
              else as.integer(r))`

const rtdal004240Source0017 = `setMethod("length", c(x = "sparseVector"),
          function(x)
              if(is.integer(r <- x@length))
                  r
              else if(r - 1 <= .Machine$integer.max)
                  as.integer(r)
              else trunc(r))`

const rtdal004240Source0021 = `setMethod("dimnames<-", c(x = "Matrix", value = "NULL"),
          function(x, value) {
              x@Dimnames <- list(NULL, NULL)
              x
          })`

const rtdal004240Source0022 = `for(.cl in c("generalMatrix", "symmetricMatrix"))
setMethod("dimnames<-", c(x = .cl, value = "NULL"),
          function(x, value) {
              if(length(x@factors))
                  x@factors <- list()
              x@Dimnames <- list(NULL, NULL)
              x
          })`

const rtdal004240Source0024 = `setMethod("dimnames<-", c(x = "MatrixFactorization", value = "NULL"),
          function(x, value) {
              x@Dimnames <- list(NULL, NULL)
              x
          })`

const rtdal004240Source0025 = `setMethod("dimnames<-", c(x = "Matrix", value = "list"),
          function(x, value) {
              x@Dimnames <- fixupDN.if.valid(value, x@Dim)
              x
          })`

const rtdal004240Source0026 = `for(.cl in c("generalMatrix", "symmetricMatrix"))
setMethod("dimnames<-", c(x = .cl, value = "list"),
          function(x, value) {
              if(length(x@factors))
                  x@factors <- list()
              x@Dimnames <- fixupDN.if.valid(value, x@Dim)
              x
          })`

