const rtdal004244Source0008 = `setMethod("diag", c(x = "indMatrix"),
          function(x = 1, nrow, ncol, names = TRUE) {
              if((m <- min(x@Dim)) == 0L)
                  return(logical(0L))
              i <- seq_len(m)
              r <- x@perm[i] == i
              if(names &&
                 !any(vapply(dn <- x@Dimnames, is.null, NA)) &&
                 identical(nms <- dn[[1L]][i], dn[[2L]][i]))
                  names(r) <- nms
              r
          })`

const rtdal004244Source0010 = `setMethod("t", c(x = "indMatrix"),
          function(x) {
              r <- new("indMatrix")
              r@Dim <- x@Dim[2:1]
              r@Dimnames = x@Dimnames[2:1]
              r@perm <- x@perm
              if(x@margin == 1L)
                  r@margin <- 2L
              r
          })`

const rtdal004244Source0015 = `setMethod("isDiagonal", c(object = "indMatrix"),
          function(object) {
              d <- object@Dim
              if((n <- d[2L]) != d[1L])
                  return(FALSE)
              all(object@perm == seq_len(n))
          })`

const rtdal004244Source0016 = "setMethod(\"isTriangular\", c(object = \"indMatrix\"),\n          function(object, upper = NA, ...) {\n              d <- object@Dim\n              if((n <- d[2L]) != d[1L])\n                  return(FALSE)\n              if(object@margin == 1L) {\n                  i <- seq_len(n)\n                  j <- object@perm\n              } else {\n                  i <- object@perm\n                  j <- seq_len(n)\n              }\n              if(is.na(upper)) {\n                  if(all(j >= i))\n                      return(`attr<-`(TRUE, \"kind\", \"U\"))\n                  if(all(i <= j))\n                      return(`attr<-`(TRUE, \"kind\", \"L\"))\n                  FALSE\n              } else if(upper) {\n                  all(j >= i)\n              } else {\n                  all(i <= j)\n              }\n          })"

const rtdal004244Source0017 = `setMethod("isSymmetric", c(object = "indMatrix"),
          function(object, checkDN = TRUE, ...) {
              d <- object@Dim
              if((n <- d[2L]) != d[1L])
                  return(FALSE)
              if(checkDN) {
                  ca <- function(check.attributes = TRUE, ...) check.attributes
                  if(ca(...) && !isSymmetricDN(object@Dimnames))
                      return(FALSE)
              }
              perm <- object@perm
              all(perm[perm] == seq_len(n))
          })`

const rtdal004244Source0018 = `.changeMargin <- function(x) {
    x@margin <- if(x@margin == 1L) 2L else 1L
    x@perm <- invertPerm(x@perm)
    x
}`

const rtdal004244Source0020 = `setAs("nsparseMatrix", "pMatrix",
      function(from) {
          d <- from@Dim
          if((n <- d[1L]) != d[2L])
              stop(gettextf("attempt to coerce non-square matrix to %s",
                            "pMatrix"),
                   domain = NA)
          from <- .M2gen(from)
          J <- new("pMatrix")
          J@Dim <- d
          J@Dimnames <- from@Dimnames
          from. <- .M2R(from)
          p <- from.@p
          m <- length(p) - 1L
          if(all(p == 0:m) && !anyDuplicated.default(j <- from.@j)) {
              J@perm <- j + 1L
              return(J)
          }
          from. <- .M2C(from)
          p <- from.@p
          n <- length(p) - 1L
          if(all(p == 0:n) && !anyDuplicated.default(i <- from.@i)) {
              J@perm <- i + 1L
              J@margin <- 2L
              return(J)
          }
          stop("matrix must have exactly one entry in each row and column")
      })`

const rtdal004244Source0022 = `setMethod("t", c(x = "pMatrix"),
          function(x) {
              r <- new("pMatrix")
              r@Dim <- x@Dim
              r@Dimnames = x@Dimnames[2:1]
              r@perm <- x@perm
              if(x@margin == 1L)
                  r@margin <- 2L
              r
          })`

