const rtdal004245Source0001 = `setMethod("anyNA", c(x = "denseMatrix"),
          function(x, recursive = FALSE) {
              cl <- .M.nonvirtual(x)
              if(substr(cl, 1L, 1L)  == "n")
                  return(FALSE)
              if((shape <- substr(cl, 2L, 2L)) == "g")
                  anyNA(x@x)
              else {
                  if(shape == "t" && x@diag != "N") {
                      x@diag <- "N"
                      if(anyNA(diag(x, names = FALSE)))
                          diag(x) <- TRUE
                  }
                  anyNA(pack(x)@x)
              }
          })`

const rtdal004245Source0003 = `setMethod("anyNA", c(x = "diagonalMatrix"),
          function(x, recursive = FALSE)
              .M.kind(x) != "n" && length(y <- x@x) > 0L && anyNA(y))`

const rtdal004245Source0006 = `setMethod("is.na", c(x = "denseMatrix"),
          function(x) {
              cl <- .M.nonvirtual(x)
              never <- substr(cl, 1L, 1L) == "n"
              substr(cl, 1L, 1L) <- "n"
              r <- new(cl)
              r@Dim <- x@Dim
              r@Dimnames <- x@Dimnames
              if((shape <- substr(cl, 2L, 2L)) != "g") {
                  r@uplo <- x@uplo
                  if(!never && shape == "t" && x@diag != "N") {
                      x@diag <- "N"
                      if(anyNA(diag(x, names = FALSE)))
                          diag(x) <- TRUE
                  }
              }
              r@x <- if(never)
                         logical(length(x@x))
                     else is.na(x@x)
              r
          })`

const rtdal004245Source0007 = `setMethod("is.na", c(x = "sparseMatrix"),
          function(x) {
              cl <- .M.nonvirtual(x)
              never <- substr(cl, 1L, 1L) == "n"
              substr(cl, 1L, 1L) <- if(never) "n" else "l"
              r <- new(cl)
              r@Dim <- d <- x@Dim
              r@Dimnames <- x@Dimnames
              if(substr(cl, 2L, 2L) != "g")
                  r@uplo <- x@uplo
              if(never) {
                  switch(substr(cl, 3L, 3L),
                         "C" = { r@p <- integer(d[2L] + 1) },
                         "R" = { r@p <- integer(d[1L] + 1) })
                  r
              } else {
                  switch(substr(cl, 3L, 3L),
                         "C" = { r@p <- x@p; r@i <- x@i },
                         "R" = { r@p <- x@p; r@j <- x@j },
                         "T" = { r@i <- x@i; r@j <- x@j })
                  r@x <- is.na(x@x)
                  .M2kind(.drop0(r), "n")
              }
          })`

