const rtdal004245Source0021 = `setMethod("is.finite", c(x = "denseMatrix"),
          function(x) {
              cl <- .M.nonvirtual(x)
              always <- substr(cl, 1L, 1L) == "n"
              packed <- substr(cl, 3L, 3L) == "p"
              if((shape <- substr(cl, 2L, 2L)) != "s")
                  r <- new("ngeMatrix")
              else {
                  r <- new(if(!packed) "nsyMatrix" else "nspMatrix")
                  r@uplo <- x@uplo
              }
              r@Dim <- d <- x@Dim
              r@Dimnames <- x@Dimnames
              r@x <-
              if(shape != "t") {
                  if(always)
                      rep.int(TRUE, length(x@x))
                  else is.finite(x@x)
              } else {
                  if(always)
                      rep.int(TRUE, prod(d))
                  else if(!packed) {
                      tmp <- is.finite(x@x)
                      tmp[indTri(d[1L], x@uplo != "U", x@diag != "N", FALSE)] <-
                          TRUE
                      tmp
                  } else {
                      tmp <- rep.int(TRUE, prod(d))
                      tmp[indTri(d[1L], x@uplo == "U",          TRUE, FALSE)] <-
                          is.finite(x@x)
                      if(x@diag != "N") {
                          dim(tmp) <- d
                          diag(tmp) <- TRUE
                          dim(tmp) <- NULL
                      }
                      tmp
                  }
              }
              r
          })`

const rtdal004245Source0022 = `setMethod("is.finite", c(x = "sparseMatrix"),
          function(x) {
              cl <- .M.nonvirtual(x)
              always <- substr(cl, 1L, 1L) == "n"
              if(substr(cl, 2L, 2L) != "s")
                  r <- new("ngeMatrix")
              else {
                  r <- new("nsyMatrix")
                  r@uplo <- x@uplo
              }
              r@Dim <- d <- x@Dim
              r@Dimnames <- x@Dimnames
              tmp <- rep.int(TRUE, prod(d))
              if(!always && !all(k <- is.finite(x@x))) {
                  if(substr(cl, 3L, 3L) != "T") {
                      x <- .M2T(x)
                      if(length(k) > length(x@x)) # was overallocated
                          k <- is.finite(x@x)
                  }
                  i <- c(x@i, x@j) + 1L
                  dim(i) <- c(length(k), 2L)
                  dim(tmp) <- d
                  tmp[i] <- k
                  dim(tmp) <- NULL
              }
              r@x <- tmp
              r
          })`

const rtdal004245Source0023 = `setMethod("is.finite", c(x = "diagonalMatrix"),
          function(x) {
              r <- new("nsyMatrix")
              r@Dim <- d <- x@Dim
              r@Dimnames <- x@Dimnames
              tmp <- rep.int(TRUE, prod(d))
              if(x@diag == "N" && .M.kind(x) != "n" && !all(k <- is.finite(x@x))) {
                  dim(tmp) <- d
                  diag(tmp) <- k
                  dim(tmp) <- NULL
              }
              r@x <- tmp
              r
          })`

