const rtdal004248Source0001 = `kroneckerDN <- function(dnX, dX = lengths(dnX, FALSE),
                        dnY, dY = lengths(dnX, FALSE),
                        sep = ":") {
    dnr <- list(NULL, NULL)
    if(identical(dnX, dnr) && identical(dnY, dnr))
        return(NULL)
    for(i in 1:2) {
        if(have.sX <- (nY <- dY[i]) && !is.null(sX <- dnX[[i]]))
            sX <- rep    (sX,  each = nY)
        if(have.sY <- (nX <- dX[i]) && !is.null(sY <- dnY[[i]]))
            sY <- rep.int(sY, times = nX)
        dnr[[i]] <-
            if(have.sX && have.sY)
                paste0(sX, sep, sY)
            else if(have.sX)
                paste0(sX, sep    )
            else if(have.sY)
                paste0(    sep, sY)
            else if(nX && nY)
                rep.int(sep, nX * nY)
    }
    dnr
}`

const rtdal004248Source0002 = `setMethod("kronecker", c(X = "diagonalMatrix", Y = "diagonalMatrix"),
          function(X, Y, FUN = "*", make.dimnames = FALSE, ...) {
              if(!(missing(FUN) || identical(FUN, "*")))
                  stop(gettextf("'%s' method must use default %s=\"%s\"",
                                "kronecker", "FUN", "*"),
                       domain = NA)
              if(any(as.double(dX <- X@Dim) * (dY <- Y@Dim) >
                     .Machine$integer.max))
                  stop(gettextf("dimensions cannot exceed %s", "2^31-1"),
                       domain = NA)
              r <- new("ddiMatrix")
              r@Dim <- dX * dY
              uX <- X@diag != "N"
              uY <- Y@diag != "N"
              if(uX && uY)
                  r@diag <- "U"
              else {
                  if(!uX) {
                      X.ii <- X@x
                      if(.M.kind(X) == "n" && anyNA(X.ii))
                          X.ii <- X.ii | is.na(X.ii)
                  }
                  if(!uY) {
                      Y.ii <- Y@x
                      if(.M.kind(Y) == "n" && anyNA(Y.ii))
                          Y.ii <- Y.ii | is.na(Y.ii)
                  }
                  r@x <-
                      if(uX)
                          rep.int(as.double(Y.ii), dX[1L])
                      else if(uY)
                          rep(as.double(X.ii), each = dY[1L])
                      else rep(X.ii, each = dY[1L]) * Y.ii
              }
              if(make.dimnames &&
                 !is.null(dnr <- kroneckerDN(dimnames(X), dX, dimnames(Y), dY)))
                  r@Dimnames <- dnr
              r
          })`

const rtdal004248Source0003 = "if(FALSE) { # --NOT YET--\nsetMethod(\"kronecker\", c(X = \"diagonalMatrix\", Y = \"denseMatrix\"),\n          function(X, Y, FUN = \"*\", make.dimnames = FALSE, ...) {\n              if(!(missing(FUN) || identical(FUN, \"*\")))\n                  stop(gettextf(\"'%s' method must use default %s=\\\"%s\\\"\",\n                                \"kronecker\", \"FUN\", \"*\"),\n                       domain = NA)\n              if(any(as.double(dX <- X@Dim) * (dY <- Y@Dim) >\n                     .Machine$integer.max))\n                  stop(gettextf(\"dimensions cannot exceed %s\", \"2^31-1\"),\n                       domain = NA)\n              uX <- X@diag != \"N\"\n              uY <- FALSE\n              shape <- .M.shape(Y)\n              r <- new(`substr<-`(\"d.CMatrix\", 2L, 2L, shape))\n              r@Dim <- dr <- dX * dY\n              if(shape != \"g\") {\n                  uplo <- r@uplo <- Y@uplo\n                  if(shape == \"t\")\n                      uY <- Y@diag != \"N\"\n              }\n              if(!all(dr)) {\n                  r@p <- integer(dr[2L] + 1)\n                  if(uX && uY)\n                      r@diag <- \"U\"\n              } else {\n                  m <- dY[1L]\n                  nX <- dX[1L]\n                  nY <- length(y <- Y@x)\n                  if(shape != \"g\" && nY > 1L && nY == prod(dY)) {\n                      Y <- pack(Y)\n                      nY <- length(y <- Y@x)\n                  }\n                  if(as.double(nX) * nY > .Machine$integer.max)\n                      stop(gettextf(\"number of nonzero entries cannot exceed %s\", \"2^31-1\"),\n                           domain = NA)\n                  if(!uX && uY) {\n                      diag(Y) <- TRUE\n                      nY <- length(y <- Y@x)\n                  }\n                  if(is.logical(y) && .M.kind(Y) == \"n\")\n                      y <- y | is.na(y)\n                  if(shape == \"g\") {\n                      r@p <- seq.int(0L, by = m, length.out = dr[2L] + 1)\n                      r@i <-\n                          rep(seq.int(0L, by = m, length.out = nX),\n                              each = nY) +\n                          0:(m-1L)\n                  } else if(uplo == \"U\") {\n                      r@p <- c(0L, cumsum(rep.int(1:m, nX)))\n                      r@i <-\n                          rep(seq.int(0L, by = m, length.out = nX),\n                              each = nY) +\n                          sequence.default(nvec = 1:m, from = 0L)\n                  } else {\n                      r@p <- c(0L, cumsum(rep.int(m:1, nX)))\n                      r@i <-\n                          rep(seq.int(0L, by = m, length.out = nX),\n                              each = nY) +\n                          sequence.default(nvec = m:1, from = 0:(m-1L))\n                  }\n                  r@x <-\n                      if(uX)\n                          rep.int(as.double(y), nX)\n                      else {\n                          X.ii <- X@x\n                          if(.M.kind(X) == \"n\" && anyNA(X.ii))\n                              X.ii <- X.ii | is.na(X.ii)\n                          as.double(y) * rep(X.ii, each = nY)\n                      }\n                  if(uX && uY)\n                      r <- ..diagN2U(r, sparse = TRUE)\n              }\n              if(make.dimnames &&\n                 !is.null(dnr <- kroneckerDN(dimnames(X), dX, dimnames(Y), dY))) {\n                  if(shape == \"s\" && !isSymmetricDN(dnr))\n                      r <- .M2gen(r)\n                  r@Dimnames <- dnr\n              }\n              r\n          })\n\nsetMethod(\"kronecker\", c(X = \"denseMatrix\", Y = \"diagonalMatrix\"),\n          function(X, Y, FUN = \"*\", make.dimnames = FALSE, ...) {\n              if(!(missing(FUN) || identical(FUN, \"*\")))\n                  stop(gettextf(\"'%s' method must use default %s=\\\"%s\\\"\",\n                                \"kronecker\", \"FUN\", \"*\"),\n                       domain = NA)\n              if(any(as.double(dX <- X@Dim) * (dY <- Y@Dim) >\n                     .Machine$integer.max))\n                  stop(gettextf(\"dimensions cannot exceed %s\", \"2^31-1\"),\n                       domain = NA)\n              shape <- .M.shape(X)\n              uX <- FALSE\n              uY <- Y@diag != \"N\"\n              r <- new(`substr<-`(\"d.CMatrix\", 2L, 2L, shape))\n              r@Dim <- dr <- dX * dY\n              if(shape != \"g\") {\n                  uplo <- r@uplo <- X@uplo\n                  if(shape == \"t\")\n                      uX <- X@diag != \"N\"\n              }\n              if(!all(dr)) {\n                  r@p <- integer(dr[2L] + 1)\n                  if(uX && uY)\n                      r@diag <- \"U\"\n              } else {\n                  m <- dX[1L]\n                  n <- dX[2L]\n                  nX <- length(x <- X@x)\n                  nY <- dY[1L]\n                  if(shape != \"g\" && nX > 1L && nX == prod(dX)) {\n                      X <- pack(X)\n                      nX <- length(x <- X@x)\n                  }\n                  if(as.double(nX) * nY > .Machine$integer.max)\n                      stop(gettextf(\"number of nonzero entries cannot exceed %s\", \"2^31-1\"),\n                           domain = NA)\n                  if(uX && !uY) {\n                      diag(X) <- TRUE\n                      nX <- length(x <- X@x)\n                  }\n                  if(is.logical(x) && .M.kind(X) == \"n\")\n                      x <- x | is.na(x)\n                  if(shape == \"g\") {\n                      x. <- function() {\n                          j <- rep(1:n, each = nY)\n                          as.vector(`dim<-`(as.double(x), dX)[, j])\n                      }\n                      r@p <- seq.int(0L, by = m, length.out = dr[2L] + 1)\n                      r@i <- rep.int(sequence.default(nvec = rep.int(m, nY),\n                                                      from = 0:(nY-1L),\n                                                      by = nY),\n                                     n)\n                      r@x <-\n                          if(uY)\n                              x.()\n                          else {\n                              Y.ii <- Y@x\n                              if(.M.kind(Y) == \"n\" && anyNA(Y.ii))\n                                  Y.ii <- Y.ii | is.na(Y.ii)\n                              x.() * rep(Y.ii, each = m)\n                          }\n                  } else if(uplo == \"U\") {\n                      rep.1.n <- rep(1:n, each = nY)\n                      s <- sequence.default(\n                          nvec = rep.1.n,\n                          from = rep(1L + cumsum(0:(n-1L)), each = nY),\n                          by = 1L)\n\n                      r@p <- c(0L, cumsum(rep.1.n))\n                      r@i <- sequence.default(nvec = rep.1.n,\n                                              from = rep.int(0:(nY-1L), n),\n                                              by = nY)\n                      r@x <-\n                          if(uY)\n                              as.double(x)[s]\n                          else\n                              as.double(x)[s] *\n                                  rep.int(rep.int(Y@x, n), rep.1.n)\n                  } else {\n                      rep.n.1 <- rep(n:1, each = nY)\n                      s <- sequence.default(\n                          nvec = rep.n.1,\n                          from = rep(1L + cumsum(c(0L, if(n > 1L) n:2)),\n                                     each = nY),\n                          by = 1L)\n                      r@p <- c(0L, cumsum(rep.n.1))\n                      r@i <- sequence.default(nvec = rep.n.1,\n                                              from = 0:(n*nY-1L),\n                                              by = nY)\n                      r@x <-\n                          if(uY)\n                              as.double(x)[s]\n                          else\n                              as.double(x)[s] *\n                                  rep.int(rep.int(Y@x, n), rep.n.1)\n                  }\n                  if(uX && uY)\n                      r <- ..diagN2U(r, sparse = TRUE)\n              }\n              if(make.dimnames &&\n                 !is.null(dnr <- kroneckerDN(dimnames(X), dX, dimnames(Y), dY))) {\n                  if(shape == \"s\" && !isSymmetricDN(dnr))\n                      r <- .M2gen(r)\n                  r@Dimnames <- dnr\n              }\n              r\n          })\n}"

const rtdal004248Source0004 = `setMethod("kronecker", c(X = "denseMatrix", Y = "denseMatrix"),
          function(X, Y, FUN = "*", make.dimnames = FALSE, ...) {
              if(!(missing(FUN) || identical(FUN, "*")))
                  stop(gettextf("'%s' method must use default %s=\"%s\"",
                                "kronecker", "FUN", "*"),
                       domain = NA)
              if(any(as.double(dX <- X@Dim) * (dY <- Y@Dim) >
                     .Machine$integer.max))
                  stop(gettextf("dimensions cannot exceed %s", "2^31-1"),
                       domain = NA)
              shape <- switch(.M.shape(X),
                              g = "g",
                              t = if(.M.shape(Y) == "t" && X@uplo == Y@uplo)
                                      "t"
                                  else "g",
                              s = if(.M.shape(Y) == "s")
                                      "s"
                                  else "g")
              r <- new(switch(shape,
                              g = "dgeMatrix",
                              t = "dtrMatrix",
                              s = "dsyMatrix"))
              r@Dim <- dr <- dX * dY
              if(shape != "g") {
                  r@uplo <- X@uplo
                  if(shape == "t" && X@diag != "N" && Y@diag != "N")
                      r@diag <- "U"
              }
              if(all(dr)) {
                  X <- .M2m(X)
                  Y <- .M2m(Y)
                  storage.mode(X) <- "double"
                  storage.mode(Y) <- "double"
                  r@x <-
                      as.vector(X[rep(seq_len(dX[1L]), each = dY[1L]),
                                  rep(seq_len(dX[2L]), each = dY[2L])]) *
                      as.vector(Y[rep.int(seq_len(dY[1L]), dX[1L]), ])
              }
              if(make.dimnames &&
                 !is.null(dnr <- kroneckerDN(dimnames(X), dX, dimnames(Y), dY))) {
                  if(shape == "s" && !isSymmetricDN(dnr))
                      r <- .M2gen(r)
                  r@Dimnames <- dnr
              }
              r
          })`

const rtdal004248Source0005 = "setMethod(\"kronecker\", c(X = \"diagonalMatrix\", Y = \"CsparseMatrix\"),\n          function(X, Y, FUN = \"*\", make.dimnames = FALSE, ...) {\n              if(!(missing(FUN) || identical(FUN, \"*\")))\n                  stop(gettextf(\"'%s' method must use default %s=\\\"%s\\\"\",\n                                \"kronecker\", \"FUN\", \"*\"),\n                       domain = NA)\n              if(any(as.double(dX <- X@Dim) * (dY <- Y@Dim) >\n                     .Machine$integer.max))\n                  stop(gettextf(\"dimensions cannot exceed %s\", \"2^31-1\"),\n                       domain = NA)\n              uX <- X@diag != \"N\"\n              uY <- FALSE\n              shape <- .M.shape(Y)\n              r <- new(`substr<-`(\"d.CMatrix\", 2L, 2L, shape))\n              r@Dim <- dr <- dX * dY\n              if(shape != \"g\") {\n                  r@uplo <- Y@uplo\n                  if(shape == \"t\" && (uX & (uY <- Y@diag != \"N\")))\n                      r@diag <- \"U\"\n              }\n              if(!all(dr))\n                  r@p <- integer(dr[2L] + 1)\n              else {\n                  if(!uX && uY)\n                      Y <- ..diagU2N(Y)\n                  if((nY <- (p <- Y@p)[length(p)]) == 0L)\n                      r@p <- integer(dr[2L] + 1)\n                  else if(as.double(nX <- dX[1L]) * nY > .Machine$integer.max)\n                      stop(gettextf(\"number of nonzero entries cannot exceed %s\", \"2^31-1\"),\n                           domain = NA)\n                  else {\n                      head. <-\n                          if(length(Y@i) > nY)\n                              function(x) x[seq_len(nY)]\n                          else identity\n                      r@p <- c(0L, cumsum(rep.int(p[-1L] - p[-length(p)], nX)))\n                      r@i <-\n                          rep(seq.int(0L, by = dY[1L], length.out = nX),\n                              each = nY) +\n                          head.(Y@i)\n                      r@x <-\n                          if(uX) {\n                              if(.M.kind(Y) == \"n\")\n                                  rep.int(1, nX * nY)\n                              else rep.int(as.double(head.(Y@x)), nX)\n                          } else {\n                              X.ii <- X@x\n                              if(.M.kind(X) == \"n\" && anyNA(X.ii))\n                                  X.ii <- X.ii | is.na(X.ii)\n                              if(.M.kind(Y) == \"n\")\n                                  rep(as.double(X.ii), each = nY)\n                              else rep(as.double(X.ii), each = nY) *\n                                      as.double(head.(Y@x))\n                          }\n                  }\n              }\n              if(make.dimnames &&\n                 !is.null(dnr <- kroneckerDN(dimnames(X), dX, dimnames(Y), dY))) {\n                  if(shape == \"s\" && !isSymmetricDN(dnr))\n                      r <- .M2gen(r)\n                  r@Dimnames <- dnr\n              }\n              r\n          })"

const rtdal004248Source0006 = "setMethod(\"kronecker\", c(X = \"CsparseMatrix\", Y = \"diagonalMatrix\"),\n          function(X, Y, FUN = \"*\", make.dimnames = FALSE, ...) {\n              if(!(missing(FUN) || identical(FUN, \"*\")))\n                  stop(gettextf(\"'%s' method must use default %s=\\\"%s\\\"\",\n                                \"kronecker\", \"FUN\", \"*\"),\n                       domain = NA)\n              if(any(as.double(dX <- X@Dim) * (dY <- Y@Dim) >\n                     .Machine$integer.max))\n                  stop(gettextf(\"dimensions cannot exceed %s\", \"2^31-1\"),\n                       domain = NA)\n              uX <- FALSE\n              uY <- Y@diag != \"N\"\n              shape <- .M.shape(X)\n              r <- new(`substr<-`(\"d.CMatrix\", 2L, 2L, shape))\n              r@Dim <- dr <- dX * dY\n              if(shape != \"g\") {\n                  r@uplo <- X@uplo\n                  if(shape == \"t\" && (uX <- X@diag != \"N\") && uY)\n                      r@diag <- \"U\"\n              }\n              if(!all(dr))\n                  r@p <- integer(dr[2L] + 1)\n              else {\n                  if(uX && !uY)\n                      X <- ..diagU2N(X)\n                  if((nX <- (p <- X@p)[length(p)]) == 0L)\n                      r@p <- integer(dr[2L] + 1)\n                  else if(as.double(nY <- dY[1L]) * nX > .Machine$integer.max)\n                      stop(gettextf(\"number of nonzero entries cannot exceed %s\", \"2^31-1\"),\n                           domain = NA)\n                  else {\n                      dp <- p[-1L] - p[-length(p)]\n                      j. <- which(dp > 0L)\n                      nj. <- length(j.)\n\n                      rep.dp <- rep(dp[j.], each = nY)\n                      s. <- sequence.default(\n                          nvec = rep.dp,\n                          from = rep(1L + p[j.], each = nY),\n                          by = 1L)\n\n                      r@p <- c(0L, cumsum(rep(dp, each = nY)))\n                      r@i <- (nY * X@i)[s.] +\n                          rep.int(rep.int(0:(nY-1L), nj.), rep.dp)\n                      r@x <-\n                          if(uY) {\n                              if(.M.kind(X) == \"n\")\n                                 rep.int(1, nX * nY)\n                              else as.double(X@x)[s.]\n                          } else {\n                              Y.ii <- Y@x\n                              if(.M.kind(Y) == \"n\" && anyNA(Y.ii))\n                                  Y.ii <- Y.ii | is.na(Y.ii)\n                              if(.M.kind(X) == \"n\")\n                                  rep.int(rep.int(as.double(Y.ii), nj.), rep.dp)\n                              else rep.int(rep.int(as.double(Y.ii), nj.), rep.dp) *\n                                       as.double(X@x)[s.]\n\n                          }\n                  }\n              }\n              if(make.dimnames &&\n                 !is.null(dnr <- kroneckerDN(dimnames(X), dX, dimnames(Y), dY))) {\n                  if(shape == \"s\" && !isSymmetricDN(dnr))\n                      r <- .M2gen(r)\n                  r@Dimnames <- dnr\n              }\n              r\n          })"

const rtdal004248Source0007 = `setMethod("kronecker", c(X = "CsparseMatrix", Y = "CsparseMatrix"),
          function(X, Y, FUN = "*", make.dimnames = FALSE, ...) {
              if(!(missing(FUN) || identical(FUN, "*")))
                  stop(gettextf("'%s' method must use default %s=\"%s\"",
                                "kronecker", "FUN", "*"),
                       domain = NA)
              if(any(as.double(dX <- X@Dim) * (dY <- Y@Dim) >
                     .Machine$integer.max))
                  stop(gettextf("dimensions cannot exceed %s", "2^31-1"),
                       domain = NA)
              uX <- uY <- FALSE
              if((sX <- .M.shape(X)) == "t")
                  uX <- X@diag != "N"
              if((sY <- .M.shape(Y)) == "t")
                  uY <- Y@diag != "N"
              shape <-
                  switch(sX,
                         g = "g",
                         t = if(sY == "t" && X@uplo == Y@uplo) "t" else "g",
                         s = if(sY == "s") "s" else "g")
              cl <- "d.CMatrix"
              if(!all(dr <- dX * dY)) {
                  substr(cl, 2L, 2L) <- shape
                  r <- new(cl)
                  r@Dim <- dr
                  r@p <- integer(dr[2L] + 1)
                  if(shape != "g") {
                      r@uplo <- X@uplo
                      if(shape == "t" && uX && uY)
                          r@diag <- "U"
                  }
              } else {
                  substr(cl, 2L, 2L) <- if(shape == "s") "g" else shape
                  r <- new(cl)
                  r@Dim <- dr
                  if(uX)
                      X <- ..diagU2N(X)
                  if(uY)
                      Y <- ..diagU2N(Y)
                  if(sY == "s")
                      Y <- .M2gen(Y)
                  else if(sX == "s")
                      X <- .M2gen(X)
                  if((nX <- (pX <- X@p)[length(pX)]) == 0L ||
                     (nY <- (pY <- Y@p)[length(pY)]) == 0L)
                      r@p <- integer(dr[2L] + 1)
                  else if(as.double(nX) * nY > .Machine$integer.max)
                      stop(gettextf("number of nonzero entries cannot exceed %s", "2^31-1"),
                           domain = NA)
                  else {
                      dpX <- pX[-1L] - (pX. <- pX[-length(pX)])
                      dpY <- pY[-1L] - (pY. <- pY[-length(pY)])

                      rep.dpX <- rep(dpX, each = dY[2L])
                      rep.dpY <- rep.int(dpY, dX[2L])

                      t1 <- rep.int(rep.dpY, rep.dpX)

                      s1 <- sequence.default(
                          nvec = rep.dpX,
                          from = rep(1L + pX., each = dY[2L]),
                          by = 1L)

                      s2 <- sequence.default(
                          nvec = t1,
                          from = rep.int(rep.int(1L + pY., dX[2L]), rep.dpX),
                          by = 1L)

                      r@p <- c(0L, cumsum(rep.dpX * dpY))
                      r@i <- rep.int((dY[1L] * X@i)[s1], t1) + Y@i[s2]
                      r@x <-
                          if(.M.kind(X) == "n") {
                              if(.M.kind(Y) == "n")
                                  rep.int(1, nX * nY)
                              else as.double(Y@x)[s2]
                          } else {
                              if(.M.kind(Y) == "n")
                                  rep.int(as.double(X@x)[s1], t1)
                              else rep.int(as.double(X@x)[s1], t1) *
                                       as.double(Y@x)[s2]
                          }
                  }
                  if(shape == "t") {
                      r@uplo <- X@uplo
                      if(uX && uY)
                          r <- ..diagN2U(r, sparse = TRUE)
                  } else if(shape == "s")
                      r <- .Call(R_sparse_force_symmetric, r, X@uplo)
              }
              if(make.dimnames &&
                 !is.null(dnr <- kroneckerDN(dimnames(X), dX, dimnames(Y), dY))) {
                  if(shape == "s" && !isSymmetricDN(dnr))
                      r <- .M2gen(r)
                  r@Dimnames <- dnr
              }
              r
          })`

