const rtdal004250Source0001 = `setMethod("Math", c(x = "denseMatrix"),
          function(x) {
              g <- get(.Generic, mode = "function")
              if(startsWith(.Generic, "cum"))
                  return(g(.M2v(x)))
              cl <- .M.nonvirtual(x)
              kind <- substr(cl, 1L, 1L)
              shape <- substr(cl, 2L, 2L)
              if (kind == "z") {
                  zero <- 0+0i; one <- 1+0i; a <- as.complex
              } else {
                  zero <- 0   ; one <- 1   ; a <- as.double
                  substr(cl, 1L, 1L) <- "d"
              }
              if(shape == "t") {
                  stay0 <- is0(a(g(zero)))
                  if(!stay0) {
                      x <- .M2gen(x)
                      substr(cl, 2L, 3L) <- "ge"
                  }
              }
              r <- new(cl)
              r@Dim <- x@Dim
              r@Dimnames <- x@Dimnames
              if(shape == "s" || (shape == "t" && stay0))
                  r@uplo <- x@uplo
              r@x <- a(g({ y <- x@x; if(kind == "n") y | is.na(y) else y }))
              if(shape == "t" && stay0 && x@diag != "N") {
                  if(is1(g1 <- a(g(one))))
                      r@diag <- "U"
                  else diag(r) <- g1
              }
              r
          })`

const rtdal004250Source0002 = `setMethod("log", c(x = "denseMatrix"),
          function(x, ...) {
              cl <- .M.nonvirtual(x)
              kind <- substr(cl, 1L, 1L)
              shape <- substr(cl, 2L, 2L)
              if(kind != "z")
                  substr(cl, 1L, 1L) <- "d"
              if(shape == "t") {
                  x <- .M2gen(x)
                  substr(cl, 2L, 3L) <- "ge"
              }
              r <- new(cl)
              r@Dim <- x@Dim
              r@Dimnames <- x@Dimnames
              if(shape == "s")
                  r@uplo <- x@uplo
              r@x <- log({ y <- x@x; if(kind == "n") y | is.na(y) else y }, ...)
              r
          })`

const rtdal004250Source0003 = `setMethod("Math", c(x = "sparseMatrix"),
          function(x) {
              g <- get(.Generic, mode = "function")
              if(startsWith(.Generic, "cum"))
                  return(g(.M2v(x)))
              cl <- .M.nonvirtual(x)
              kind <- substr(cl, 1L, 1L)
              shape <- substr(cl, 2L, 2L)
              repr <- substr(cl, 3L, 3L)
              if (kind == "z") {
                  zero <- 0+0i; one <- 1+0i; a <- as.complex
              } else {
                  zero <- 0   ; one <- 1   ; a <- as.double
                  substr(cl, 1L, 1L) <- "d"
              }
              stay0 <- is0(g0 <- a(g(zero)))
              if(!stay0)
                  substr(cl, 2L, 3L) <- if(shape == "s") "sy" else "ge"
              r <- new(cl)
              r@Dim      <- x@Dim
              r@Dimnames <- x@Dimnames
              if(shape == "s" || (shape == "t" && stay0))
                  r@uplo <- x@uplo
              if(!stay0) {
                  y <- .Call(CR2spV, if(repr == "T") .M2C(x) else x)
                  tmp <- rep.int(g0, y@length)
                  tmp[y@i] <- a(g(if(kind == "n") one else y@x))
                  r@x <- tmp
              } else {
                  if(shape == "t" && x@diag != "N") {
                      if(is1(a(g(one))))
                          r@diag <- "U"
                      else diag(x) <- TRUE
                  }
                  nnz <- length(
                      switch(repr,
                             "C" = { r@p <- x@p; r@i <- x@i },
                             "R" = { r@p <- x@p; r@j <- x@j },
                             "T" = { r@i <- x@i; r@j <- x@j }))
                  r@x <- if(kind == "n") rep.int(a(g(one)), nnz) else a(g(x@x))
              }
              r
          })`

const rtdal004250Source0004 = `setMethod("log", c(x = "sparseMatrix"),
          function(x, ...) {
              cl <- .M.nonvirtual(x)
              kind <- substr(cl, 1L, 1L)
              shape <- substr(cl, 2L, 2L)
              repr <- substr(cl, 3L, 3L)
              if(kind == "z") {
                  zero <- 0+0i; one <- 1+0i
              } else {
                  zero <- 0   ; one <- 1
                  substr(cl, 1L, 1L) <- "d"
              }
              substr(cl, 2L, 3L) <- if(shape == "s") "sy" else "ge"
              r <- new(cl)
              r@Dim      <- x@Dim
              r@Dimnames <- x@Dimnames
              if(shape == "s")
                  r@uplo <- x@uplo
              y <- .Call(CR2spV, if(repr == "T") .M2C(x) else x)
              tmp <- rep.int(log(zero, ...), y@length)
              tmp[y@i] <- log(if(kind == "n") one else y@x, ...)
              r@x <- tmp
              r
          })`

const rtdal004250Source0005 = `setMethod("Math", c(x = "diagonalMatrix"),
          function(x) {
              g <- get(.Generic, mode = "function")
              if(startsWith(.Generic, "cum"))
                  return(g(.M2v(x)))
              cl <- .M.nonvirtual(x)
              kind <- substr(cl, 1L, 1L)
              if (kind == "z") {
                  zero <- 0+0i; one <- 1+0i; a <- as.complex
              } else {
                  zero <- 0   ; one <- 1   ; a <- as.double
                  substr(cl, 1L, 1L) <- "d"
              }
              stay0 <- is0(g0 <- a(g(zero)))
              if(!stay0)
                  substr(cl, 2L, 3L) <- "ge"
              r <- new(cl)
              r@Dim <- d <- x@Dim
              r@Dimnames <- x@Dimnames
              if(!stay0) {
                  if((n <- d[2L]) > 0L) {
                      tmp <- matrix(g0, n, n)
                      diag(tmp) <- a(g(if(x@diag != "N") one else { y <- x@x; if(kind == "n" && anyNA(y)) y | is.na(y) else y }))
                      dim(tmp) <- NULL
                      r@x <- tmp
                  }
              } else {
                  if(x@diag != "N") {
                      if(is1(g1 <- a(g(one))))
                          r@diag <- "U"
                      else r@x <- rep.int(g1, d[1L])
                  } else r@x <- a(g({ y <- x@x; if(kind == "n" && anyNA(y)) y | is.na(y) else y }))
              }
              r
          })`

