const rtdal004250Source0009 = `setMethod("Math", c(x = "sparseVector"),
          function(x) {
              g <- get(.Generic, mode = "function")
              if(startsWith(.Generic, "cum"))
                  return(g(.V2v(x)))
              kind <- .M.kind(x)
              if(kind == "z") {
                  zero <- 0+0i; one <- 1+0i; l <- "z"
              } else if(kind == "d" || .Generic != "abs") {
                  zero <- 0   ; one <- 1   ; l <- "d"
              } else {
                  zero <- 0L  ; one <- 1L  ; l <- "i"
              }
              if(isN0(g0 <- g(zero))) {
                  r <- rep.int(g0, x@length)
                  if((nnz <- length(x@i)) > 0L)
                      r[x@i] <- if(kind == "n") rep.int(g(one), nnz) else g(x@x)
              } else {
                  r <- new(paste0(l, "sparseVector"))
                  r@length <- x@length
                  r@i <- x@i
                  if((nnz <- length(x@i)) > 0L)
                      r@x <- if(kind == "n") rep.int(g(one), nnz) else g(x@x)
              }
              r
          })`

const rtdal004250Source0010 = `setMethod("log", c(x = "sparseVector"),
          function(x, ...) {
              kind <- .M.kind(x)
              if(kind == "z") {
                  zero <- 0+0i; one <- 1+0i
              } else {
                  zero <- 0   ; one <- 1
              }
              r <- rep.int(log(zero, ...), x@length)
              if(length(x@i) > 0L)
                  r[x@i] <- log(if(kind == "n") one else x@x, ...)
              r
          })`

const rtdal004250Source0011 = `setMethod("Math2", c(x = "Matrix"),
          function(x, digits) {
              x <- .indefinite(.M2kind(x, ","))
              x@x <- get(.Generic, mode = "function")(x@x, digits = digits)
              if(.hasSlot(x, "factors") && length(x@factors) > 0L)
                  x@factors <- list()
              x
          })`

const rtdal004250Source0012 = `setMethod("Math2", c(x = "sparseVector"),
          function(x, digits) {
              x <- .V2kind(x, ",")
              x@x <- get(.Generic, mode = "function")(x@x, digits = digits)
              x
          })`

const rtdal004250Source0013 = `setMethod("zapsmall", signature(x = "Matrix"),
          function(x, digits = getOption("digits"),
                   mFUN = function(x, ina) max(abs(x[!ina])), min.d = 0L, ...) {
              x <- .indefinite(.M2kind(x, ","))
              x@x <- zapsmall(x@x, digits=digits, mFUN=mFUN, min.d=min.d, ...)
              if(.hasSlot(x, "factors") && length(x@factors) > 0L)
                  x@factors <- list()
              x
          })`

const rtdal004250Source0014 = `setMethod("zapsmall", signature(x = "sparseVector"),
          function(x, digits = getOption("digits"),
                   mFUN = function(x, ina) max(abs(x[!ina])), min.d = 0L, ...) {
              x <- .V2kind(x, ",")
              x@x <- zapsmall(x@x, digits=digits, mFUN=mFUN, min.d=min.d, ...)
              x
          })`

