const rtdal004251Source0101 = `setMethod("crossprod", c(x = "diagonalMatrix", y = "missing"),
          function(x, y = NULL, boolArith = NA, ...) {
              boolArith <- !is.na(boolArith) && boolArith
              r <- new(if(boolArith) "ndiMatrix" else "ddiMatrix")
              r@Dim <- x@Dim
              r@Dimnames <- x@Dimnames[c(2L, 2L)]
              if(x@diag != "N")
                  r@diag <- "U"
              else {
                  xii <- x@x
                  r@x <-
                      if(boolArith)
                          as.logical(xii)
                      else {
                          if(.M.kind(x) == "n" && anyNA(xii))
                              xii <- xii | is.na(xii)
                          as.double(xii * xii)
                      }
              }
              r
          })`

