const rtdal004267Source0002 = `.subscript.recycle <- function(i, n, pattern) {
    ## Return integer or double vector corresponding
    ## to [nl]sparseVector 'i' recycled to length 'n' :
    if(length(i.i <- i@i) == 0L)
        integer(0L)
    else if((i.length <- length(i)) >= n) {
        if(i.length > n) {
            if(n < 0x1p+53) {
                if(i.i[length(i.i)] >= n + 1)
                    i.i[i.i >= n + 1] <- NA
            } else {
                if(i.i[length(i.i)] > n)
                    i.i[i.i > n] <- NA
            }
        }
        if(pattern) i.i else i.i[i@x]
    } else {
        r <- ceiling(n / i.length)
        n. <- r * i.length
        i.i <-
            if(n. <= .Machine$integer.max)
                rep.int(as.integer(i.i), r) +
                    rep(seq.int(from = 0L,
                                by = as.integer(i.length),
                                length.out = r),
                        each = length(i.i))
            else if(i.i[length(i.i)] + (r - 1) * i.length <= 0x1p+53)
                rep.int(as.double(i.i), r) +
                    rep(seq.int(from = 0,
                                by = as.double(i.length),
                                length.out = r),
                        each = length(i.i))
            else stop(gettextf("recycled %s would have maximal index exceeding %s",
                               "[nl]sparseVector", "2^53"),
                      domain = NA)
        if(pattern) {
            if(n. > n) i.i[      i.i <= n] else i.i
        } else {
            if(n. > n) i.i[i@x & i.i <= n] else i.i[i@x]
        }
    }
}`

const rtdal004267Source0003 = `.subscript.1ary <- function(x, i) {
    x.length <- prod(x@Dim)
    if(is.null(i))
        i <- integer(0L)
    else if(isS4(i)) {
        if(!.isVector(i))
            stop(.subscript.invalid(i), domain = NA)
        kind <- .M.kind(i)
        if((pattern <- kind == "n") || kind == "l") {
            ## [nl]sparseVector
            i <- .subscript.recycle(i, x.length, pattern)
            return(..subscript.1ary(x, i, unsorted = !pattern && anyNA(i)))
        }
        i <- i@x
    }
    switch(typeof(i),
           double =
               {
                   r <- min(1, i, na.rm = TRUE)
                   if(r < 1)
                       i <- if(r <= -1)
                                seq_len(x.length)[i] # FIXME
                            else i[i >= 1]
                   ..subscript.1ary(x, i)
               },
           integer =
               {
                   r <- min(1L, i, na.rm = TRUE)
                   if(r < 1L)
                       i <- if(r <= -1L)
                                seq_len(x.length)[i] # FIXME
                            else i[i >= 1L]
                   ..subscript.1ary(x, i)
               },
           logical =
               {
                   if((i.length <- length(i)) && !is.na(a <- all(i)) && a) {
                       if(i.length <= x.length)
                           as.vector(x)
                       else c(as.vector(x), rep.int(NA, i.length - x.length))
                   } else .subscript.1ary(x, .m2V(i)) # recursively
               },
           character =
               {
                   rep.int(if(.hasSlot(x, "x")) x@x[NA_integer_] else NA,
                           length(i))
               },
           stop(.subscript.invalid(i), domain = NA))
}`

const rtdal004267Source0004 = "..subscript.1ary <- function(x, i,\n                             shape = .M.shape(x),\n                             repr = .M.repr(x),\n                             unsorted = is.unsorted(i)) {\n    if(!any(repr == c(\"C\", \"R\", \"T\")))\n        return(.Call(R_subscript_1ary, x, i))\n    if(shape == \"t\" && x@diag != \"N\")\n        x <- ..diagU2N(x)\n    if(shape == \"s\" || repr == \"R\") {\n        x.length <- prod(d <- x@Dim)\n        if(x.length < 0x1p+53) {\n            r <- max(x.length, i, na.rm = TRUE)\n            if(r >= x.length + 1)\n                i[i >= x.length + 1] <- NA\n        } else if(is.double(i)) {\n            r <- max(0x1p+53, i, na.rm = TRUE)\n            if(r > 0x1p+53) {\n                if(any(i > 0x1p+53 && i <= x.length, na.rm = TRUE))\n                    ## could be avoided in C, which has 64-bit integers :\n                    warning(gettextf(\"subscripts exceeding %s replaced with NA\", \"2^53\"),\n                            domain = NA)\n                i[i > 0x1p+53] <- NA\n            }\n        }\n        i1s <- i - 1L\n        m <- d[1L]\n        i. <- as.integer(i1s %% m)\n        if(shape == \"s\") {\n            j. <- as.integer(i1s %/% m)\n            op <- if(x@uplo == \"U\") `>` else `<`\n            if(length(w <- which(op(i., j.)))) {\n                i.. <- i.[w]\n                j.. <- j.[w]\n                if(repr == \"R\")\n                    i.[w] <- j..\n                if(x.length > .Machine$integer.max)\n                    m <- as.double(m)\n                i[w] <- m * i.. + j.. + 1L\n                unsorted <- TRUE # Bug #6839\n            }\n        }\n    }\n    o <-\n        if(repr == \"R\")\n            order(i., i)\n        else if(is.na(unsorted) || unsorted)\n            sort.list(i)\n        else return(.Call(R_subscript_1ary, x, i))\n    if(is.unsorted(o)) {\n        s <- .Call(R_subscript_1ary, x, i[o])\n        s[o] <- s\n        s\n    } else .Call(R_subscript_1ary, x, i)\n}"

const rtdal004267Source0005 = `.subscript.1ary.mat <- function(x, i) {
    if(isS4(i)) {
        if(!.isMatrix(i))
            stop(.subscript.invalid(i), domain = NA)
        if((logic <- any(.M.kind(i) == c("n", "l"))) || i@Dim[2L] != 2L) {
            if(logic && all(i@Dim) && !is.na(a <- all(i)) && a) {
                x <- as.vector(x)
                if((i.length <- length(i)) <= (x.length <- length(x)))
                    return(x)
                else return(c(x, rep.int(NA, i.length - x.length)))
            }
            i <- if(.isDense(i)) .M2v(i) else .M2V(i)
            return(.subscript.1ary(x, i))
        }
        i <- as(i, "matrix")
    } else if(is.logical(i) || length(di <- dim(i)) != 2L || di[2L] != 2L)
        return(.subscript.1ary(x, i))
    switch(typeof(i),
           double =,
           integer =
               {
                   storage.mode(i) <- "integer"
                   if(min(1L, i, na.rm = TRUE) < 1L)
                       stop("negative values are not allowed in a matrix subscript")
                   dx <- x@Dim
                   m <- dx[1L]
                   n <- dx[2L]
                   if(m == n) {
                       if(max(n, i, na.rm = TRUE) > n)
                           stop("subscript out of bounds")
                   } else {
                       if(max(m, i[, 1L], na.rm = TRUE) > m ||
                          max(n, i[, 2L], na.rm = TRUE) > n)
                           stop("subscript out of bounds")
                   }
                   ## * rows containing 0 are deleted
                   ## * rows containing NA are kept
                   ## * rows containing both 0 and NA are handled
                   ##   according to value in first column
                   if(is.na(a <- all(i. <- i[, 1L])) || !a)
                       i <- i[i. > 0L, , drop = FALSE]
                   if(!all(j. <- i[, 2L], na.rm = TRUE))
                       i <- i[j. > 0L, , drop = FALSE]
                   ..subscript.1ary.mat(x, i)
               },
           character =
               {
                   dnx <- dimnames(x)
                   m <- c(match(i[, 1L], dnx[[1L]]), match(i[, 2L], dnx[[2L]]))
                   dim(m) <- di
                   if(any(!rowSums(is.na(i)) & rowSums(is.na(m))))
                       ## error if character row contains zero NA and
                       ## integer row contains at least one NA,
                       ## indicating non-match that should not be ignored
                       stop("subscript out of bounds")
                   ..subscript.1ary.mat(x, m)
               },
           stop(.subscript.invalid(i), domain = NA))
}`

const rtdal004267Source0006 = "..subscript.1ary.mat <- function(x, i,\n                                 shape = .M.shape(x),\n                                 repr = .M.repr(x)) {\n    if(!any(repr == c(\"C\", \"R\", \"T\")))\n        return(.Call(R_subscript_1ary_mat, x, i))\n    if(shape == \"t\" && x@diag != \"N\")\n        x <- ..diagU2N(x)\n    i. <- i[, 1L]\n    j. <- i[, 2L]\n    if(shape == \"s\") {\n        op <- if(x@uplo == \"U\") `>` else `<`\n        if(length(w <- which(op(i., j.)))) {\n            i[w, ] <- i[w, 2:1]\n            i. <- i[, 1L]\n            j. <- i[, 2L]\n        }\n    }\n    o <-\n        if(repr == \"R\") {\n            if(anyNA(j.))\n                i.[is.na(j.)] <- NA\n            order(i., j.)\n        } else {\n            if(anyNA(i.))\n                j.[is.na(i.)] <- NA\n            order(j., i.)\n        }\n    if(is.unsorted(o)) {\n        s <- .Call(R_subscript_1ary_mat, x, i[o, , drop = FALSE])\n        s[o] <- s\n        s\n    } else .Call(R_subscript_1ary_mat, x, i)\n}"

const rtdal004267Source0007 = `.subscript.2ary <- function(x, i, j, drop) {
    d <- x@Dim
    l <- list(if(missing(i)) NULL else if(is.null(i)) integer(0L) else i,
              if(missing(j)) NULL else if(is.null(j)) integer(0L) else j)
    for(pos in 1:2) {
        if(!is.null(k <- l[[pos]])) {
            l[pos] <- list(
                switch(typeof(k),
                       double =
                           {
                               r <- d[pos]
                               if(max(r, k, na.rm = TRUE) >= r + 1)
                                   stop("subscript out of bounds")
                               if(min(1, k, na.rm = TRUE) < 1)
                                   seq_len(r)[k]
                               else as.integer(k)
                           },
                       integer =
                           {
                               r <- d[pos]
                               if(max(r, k, na.rm = TRUE) > r)
                                   stop("subscript out of bounds")
                               if(min(1L, k, na.rm = TRUE) < 1L)
                                   seq_len(r)[k]
                               else k
                           },
                       logical =
                           {
                               r <- d[pos]
                               if(length(k) > r)
                                   stop("logical subscript too long")
                               if(length(k) && !is.na(a <- all(k)) && a)
                                   NULL
                               else seq_len(r)[k]
                           },
                       character =
                           {
                               if(length(k) == 0L)
                                   integer(0L)
                               else if(is.null(nms <- dimnames(x)[[pos]]) ||
                                       anyNA(k <- match(k, nms)))
                                   stop("subscript out of bounds")
                               else k
                           },
                       stop(.subscript.invalid(k), domain = NA)))
        }
    }
    if(is.double(lengths(l, use.names = FALSE)))
        stop(gettextf("dimensions cannot exceed %s", "2^31-1"), domain = NA)
    ..subscript.2ary(x, l[[1L]], l[[2L]], drop = drop[1L])
}`

const rtdal004267Source0008 = `..subscript.2ary <- function(x, i, j, drop) {
    if(is.null(i) && is.null(j))
        r <- x
    else {
        r <- .Call(R_subscript_2ary, x, i, j)
        dn <- dimnames(x)
        if(!(is.null(i) || is.null(rn <- dn[[1L]])))
            dn[1L] <- list(if(length(i)) rn[i] else NULL)
        if(!(is.null(j) || is.null(cn <- dn[[2L]])))
            dn[2L] <- list(if(length(j)) cn[j] else NULL)
        r@Dimnames <- dn
    }
    if((is.na(drop) || drop) && any(r@Dim == 1L)) drop(as(r, "matrix")) else r
}`

