const rtdal004324Source0004 = `qq.gam <- function(object, rep=0, level=.9,s.rep=10,
                   type=c("deviance","pearson","response"),
                   pch=".", rl.col=2, rep.col="gray80",...) {
## get deviance residual quantiles under good fit
  type <- match.arg(type)
  ylab <- paste(type,"residuals")

  if (inherits(object,c("glm","gam"))) {
    if (is.null(object$sig2)) object$sig2 <- summary(object)$dispersion
  } else stop("object is not a glm or gam")

  ## in case of NA & na.action="na.exclude", we need the "short" residuals:
  object$na.action <- NULL
  D <- residuals(object,type=type)

  if (object$method %in% c("PQL","lme.ML","lme.REML","lmer.REML","lmer.ML","glmer.ML")) {
    ## then it's come out of a gamm fitter and qq.gam can't see the random effects
    ## that would be necessary to get quantiles. Fall back to normal QQ plot.
    qqnorm(D,ylab=ylab,pch=pch,...)
    return()
  }

  lim <- Dq <- NULL
  if (rep==0) { 
    fam <- fix.family.qf(object$family)
    if (is.null(fam$qf))
      rep <- 50 ## try simulation if quantile function not available
    level <- 0
  } 
  n <- length(D)
  if (rep > 0) { ## simulate quantiles
    fam <- fix.family.rd(object$family)
    if (!is.null(fam$rd)) {
      ##d <- rep(0,0)
      ## simulate deviates... 
      dm <- matrix(0,n,rep)
      for (i in 1:rep) { 
        yr <- fam$rd(object$fitted.values, object$prior.weights, object$sig2)
        #di <- fam$dev.resids(yr,object$fitted.values,object$prior.weights)^.5*
        #       sign(yr-object$fitted.values)
        object$y <- yr
        dm[,i] <- sort(residuals(object,type=type))
        #d <- c(d,sort(di))
      }
      # n <- length(D)
      Dq <- quantile(as.numeric(dm),(1:n - .5)/n) 
    
      ## now get simulation limits on QQ plot
      #dm <- matrix(d,length(Dq),rep)
      alpha <- (1-level)/2
      if (alpha>.5||alpha<0) alpha <- .05
      if (level>0&&level<1) lim <- apply(dm,1,FUN=quantile,p=c(alpha,1-alpha)) else
      if (level >= 1) lim <- level 
    }
  } else {
    ## ix <- sort.int(D,index.return=TRUE)$ix ## messes up under multiple ties!
    #ix <- rank(D)
    #U <- (ix-.5)/length(D) ## code used pre-randomization - not needed
    U <- (1:n-.5)/n
    if (!is.null(fam$qf)) { 
      dm <- matrix(0,n,s.rep)
      for (i in 1:s.rep) { 
        U <- sample(U,n) ## randomize uniform quantiles w.r.t. obs
        q0 <- fam$qf(U,object$fitted.values,object$prior.weights,object$sig2)
        object$y <- q0
        dm[,i] <- sort(residuals(object,type=type)) ## original proposal
      }
      Dq <- sort(rowMeans(dm))
    }
  }
 
  if (!is.null(Dq))  
  { qqplot(Dq,D,ylab=ylab,xlab="theoretical quantiles",ylim=range(c(lim,D)),
           pch=pch,...)
    abline(0,1,col=rl.col)
    if (!is.null(lim)) {
      if (level>=1) for (i in 1:rep) lines(Dq,dm[,i],col=rep.col) else {
        n <- length(Dq)
        polygon(c(Dq,Dq[n:1],Dq[1]),c(lim[1,],lim[2,n:1],lim[1,1]),col=rep.col,border=NA)
      }
      abline(0,1,col=rl.col) 
    }
    points(Dq,sort(D),pch=pch,...)
    return(invisible(Dq))
  } else qqnorm(D,ylab=ylab,pch=pch,...)
}`

const rtdal004324Source0005 = `k.check <- function(b,subsample=5000,n.rep=400) {
## function to check k in a gam fit... 
## does a randomization test looking for evidence of residual 
## pattern attributable to covariates of each smooth. 
  m <- length(b$smooth)
  if (m==0) return(NULL)
  rsd <- residuals(b)
 
  ve <- rep(0,n.rep)
  p.val<-v.obs <- kc <- edf<- rep(0,m)
  snames <- rep("",m)
  n <- nrow(b$model)
  if (n>subsample) { ## subsample to avoid excessive cost
    ind <- sample(1:n,subsample)
    modf <- b$model[ind,] 
    rsd <- rsd[ind]
  } else modf <- b$model
  nr <- length(rsd)
  for (k in 1:m) { ## work through smooths
    ok <- TRUE
    b$smooth[[k]]$by <- "NA" ## can't deal with by variables
    dat <- ExtractData(b$smooth[[k]],modf,NULL)$data
    if (!is.null(attr(dat,"index"))||!is.null(attr(dat[[1]],"matrix"))||is.matrix(dat[[1]])) ok <- FALSE
    if (ok) dat <- as.data.frame(dat)
    snames[k] <- b$smooth[[k]]$label
    ind <- b$smooth[[k]]$first.para:b$smooth[[k]]$last.para
    kc[k] <- length(ind)
    edf[k] <- sum(b$edf[ind]) 
    nc <- b$smooth[[k]]$dim
    if (ok && ncol(dat)>nc) dat <- dat[,1:nc,drop=FALSE] ## drop any by variables
    for (j in 1:nc) if (is.factor(dat[[j]])) ok <- FALSE 
    if (!ok) {
      p.val[k] <- v.obs[k] <- NA ## can't do this test with summation convention/factors
    } else { ## normal term
      if (nc==1) { ## 1-D term
        e <- diff(rsd[order(dat[,1])])
        v.obs[k] <- mean(e^2)/2
        for (i in 1:n.rep) {
          e <- diff(rsd[sample(1:nr,nr)]) ## shuffle 
          ve[i] <-  mean(e^2)/2
        }
        p.val[k] <- mean(ve<v.obs[k])
        v.obs[k] <- v.obs[k]/mean(rsd^2)
      } else { ## multi-D 
        if (!is.null(b$smooth[[k]]$margin)) { ## tensor product (have to consider scaling)
          ## get the scale factors...
          beta <- coef(b)[ind]
          f0 <- PredictMat(b$smooth[[k]],dat)%*%beta
          gr.f <- rep(0,ncol(dat))
          for (i in 1:nc) {
            datp <- dat;dx <- diff(range(dat[,i]))/1000
            datp[,i] <- datp[,i] + dx
            fp <- PredictMat(b$smooth[[k]],datp)%*%beta
            gr.f[i] <- mean(abs(fp-f0))/dx
          }
          for (i in 1:nc) { ## rescale distances
            dat[,i] <- dat[,i] - min(dat[,i])
            dat[,i] <- gr.f[i]*dat[,i]/max(dat[,i])
          }
        }
        nn <- 3
        ni <- nearest(nn,as.matrix(dat))$ni
        e <- rsd - rsd[ni[,1]]
        for (j in 2:nn) e <- c(e,rsd-rsd[ni[,j]])
        v.obs[k] <- mean(e^2)/2
        for (i in 1:n.rep) {
          rsdr <- rsd[sample(1:nr,nr)] ## shuffle
          e <- rsdr - rsdr[ni[,1]]
          for (j in 2:nn) e <- c(e,rsdr-rsdr[ni[,j]])
          ve[i] <-  mean(e^2)/2
        }
        p.val[k] <- mean(ve<v.obs[k])
        v.obs[k] <- v.obs[k]/mean(rsd^2)
      }
    }
  }
  k.table <- cbind(kc,edf,v.obs, p.val)
  dimnames(k.table) <- list(snames, c("k\'","edf","k-index", "p-value"))
  k.table
}`

const rtdal004324Source0006 = "gam.check <- function(b, old.style=FALSE,\n\t\t      type=c(\"deviance\",\"pearson\",\"response\"), \n                      k.sample=5000,k.rep=200,\n\t\t      ## arguments passed to qq.gam() {w/o warnings !}:\n\t\t      rep=0, level=.9, rl.col=2, rep.col=\"gray80\", ...)\n## takes a fitted gam object and produces some standard diagnostic plots\n{\n  type <- match.arg(type)\n  resid <- residuals(b, type=type)\n  linpred <- if (is.matrix(b$linear.predictors)&&!is.matrix(resid)) \n             napredict(b$na.action, b$linear.predictors[,1]) else \n             napredict(b$na.action, b$linear.predictors)\n##  if (b$method%in%c(\"GCV\",\"GACV\",\"UBRE\",\"REML\",\"ML\",\"P-ML\",\"P-REML\",\"mle.REML\",\"mle.ML\",\"PQL\")) { \n    if (is.null(.Platform$GUI) || .Platform$GUI != \"RStudio\") old.par <- par(mfrow=c(2,2))\n    if (old.style)\n      qqnorm(resid,...)\n    else\n      qq.gam(b, rep=rep, level=level, type=type, rl.col=rl.col, rep.col=rep.col, ...)\n    plot(linpred, resid,main=\"Resids vs. linear pred.\",\n         xlab=\"linear predictor\",ylab=\"residuals\",...)\n    hist(resid,xlab=\"Residuals\",main=\"Histogram of residuals\",...)\n    fv <- if (inherits(b$family,\"extended.family\")) predict(b,type=\"response\") else fitted(b)\n    if (is.matrix(fv)&&!is.matrix(b$y)) fv <- fv[,1]\n    plot(fv, napredict(b$na.action, b$y),\n         xlab=\"Fitted Values\",ylab=\"Response\",main=\"Response vs. Fitted Values\",...)\n\n    gamm <- !(b$method%in%c(\"GCV\",\"GACV\",\"UBRE\",\"REML\",\"ML\",\"P-ML\",\"P-REML\",\"fREML\",\"NCV\")) ## gamm `gam' object\n\n    #if (is.null(.Platform$GUI) || .Platform$GUI != \"RStudio\") par(old.par)\n    #   return(invisible())\n    #}\n    ## now summarize convergence information \n    if (gamm) {\n      cat(\"\\n\\'gamm\\' based fit - care required with interpretation.\")\n      cat(\"\\nChecks based on working residuals may be misleading.\")\n    } else { \n      cat(\"\\nMethod:\",b$method,\"  Optimizer:\",b$optimizer)\n      if (!is.null(b$outer.info)) { ## summarize convergence information\n        if (b$optimizer[2]%in%c(\"newton\",\"bfgs\"))\n        { boi <- b$outer.info\n          cat(\"\\n\",boi$conv,\" after \",boi$iter,\" iteration\",sep=\"\")\n          if (boi$iter==1) cat(\".\") else cat(\"s.\")\n          cat(\"\\nGradient range [\",min(boi$grad),\",\",max(boi$grad),\"]\",sep=\"\")\n          cat(\"\\n(score \",b$gcv.ubre,\" & scale \",b$sig2,\").\",sep=\"\")\n          ev <- eigen(boi$hess)$values\n          if (min(ev)>0) cat(\"\\nHessian positive definite, \") else cat(\"\\n\")\n          cat(\"eigenvalue range [\",min(ev),\",\",max(ev),\"].\\n\",sep=\"\")\n        } else { ## just default print of information ..\n          cat(\"\\n\");print(b$outer.info)\n        }\n      } else { ## no sp, perf iter or AM case\n        if (length(b$sp)==0) ## no sp's estimated  \n          cat(\"\\nModel required no smoothing parameter selection\")\n        else { \n          cat(\"\\nSmoothing parameter selection converged after\",b$mgcv.conv$iter,\"iteration\")       \n          if (b$mgcv.conv$iter>1) cat(\"s\")\n         \n          if (!b$mgcv.conv$fully.converged)\n          cat(\" by steepest\\ndescent step failure.\\n\") else cat(\".\\n\")\n          cat(\"The RMS\",b$method,\"score gradient at convergence was\",b$mgcv.conv$rms.grad,\".\\n\")\n          if (b$mgcv.conv$hess.pos.def)\n          cat(\"The Hessian was positive definite.\\n\") else cat(\"The Hessian was not positive definite.\\n\")\n          #cat(\"The estimated model rank was \",b$mgcv.conv$rank,\n          #           \" (maximum possible: \",b$mgcv.conv$full.rank,\")\\n\",sep=\"\")\n        }\n      }\n      if (!is.null(b$rank)) {\n        cat(\"Model rank = \",b$rank,\"/\",length(b$coefficients),\"\\n\")\n      }\n    } ## if gamm\n    cat(\"\\n\")\n    ## now check k\n    kchck <- k.check(b,subsample=k.sample,n.rep=k.rep)\n    if (!is.null(kchck)) {\n      cat(\"Basis dimension (k) checking results. Low p-value (k-index<1) may\\n\") \n      cat(\"indicate that k is too low, especially if edf is close to k\\'.\\n\\n\")\n      printCoefmat(kchck,digits=3);\n    }\n    if (is.null(.Platform$GUI) ||.Platform$GUI != \"RStudio\") par(old.par)\n##  } else plot(linpred,resid,xlab=\"linear predictor\",ylab=\"residuals\",...)\n}"

const rtdal004324Source0007 = `plot.random.effect <- function(x,P=NULL,data=NULL,label="",
                     partial.resids=FALSE,rug=TRUE,se=TRUE,scale=-1,n=100,n2=40,n3=3,
                     theta=30,phi=30,jit=FALSE,xlab=NULL,ylab=NULL,main=NULL,
                     ylim=NULL,xlim=NULL,too.far=0.1,shade.col="gray80",
                     shift=0,trans=I,by.resids=FALSE,scheme=0,...) {
## plot method for a "random.effect" smooth class
 
  if (is.null(P)) { ## get plotting information...
    if (!x$plot.me) return(NULL) else { ## shouldn't or can't plot 
      raw <- data[x$term][[1]]
      p <- x$last.para - x$first.para + 1
      X <- diag(p)   # prediction matrix for this term
      if (is.null(xlab)) xlabel<- "Gaussian quantiles" else xlabel <- xlab
      if (is.null(ylab)) ylabel <- "effects" else ylabel <- ylab
      if (!is.null(main)) label <- main
      return(list(X=X,scale=FALSE,se=FALSE,raw=raw,xlab=xlabel,ylab=ylabel,
             main=label))

    } ## end of basic plot data production 
  } else { ## produce plot
    b <- as.numeric(trans(P$fit+shift))
    qqnorm(b,main=P$main,xlab=P$xlab,ylab=P$ylab,...)
    qqline(b)
  } ## end of plot production
}`

const rtdal004324Source0010 = `plot.sos.smooth <- function(x,P=NULL,data=NULL,label="",
                     partial.resids=FALSE,rug=TRUE,se=TRUE,scale=-1,n=100,n2=40,n3=3,
                     theta=30,phi=30,jit=FALSE,xlab=NULL,ylab=NULL,main=NULL,
                     ylim=NULL,xlim=NULL,too.far=0.1,shade.col="gray80",
                     shift=0,trans=I,by.resids=FALSE,scheme=0,hcolors=heat.colors(100),
                     contour.col=4,...) {
## plot method function for sos.smooth terms
  if (scheme>1) return(plot.mgcv.smooth(x,P=P,data=data,label=label,
                     partial.resids=partial.resids,rug=rug,se=se,scale=scale,n=n,n2=n2,
                     theta=theta,phi=phi,jit=jit,xlab=xlab,ylab=ylab,main=main,
                     ylim=ylim,xlim=xlim,too.far=too.far,shade.col=shade.col,
                     shift=shift,trans=trans,by.resids=by.resids,scheme=scheme-2,
                     hcolors=hcolors,contour.col=contour.col,...))
  ## convert location of pole in plotting grid to radians
  phi <- phi*pi/180
  theta <- theta*pi/180
  
  ## re-map to sensible values...
  theta <- theta%%(2*pi)
  if (theta>pi) theta <- theta - 2*pi
 
  phi <- phi%%(2*pi)
  if (phi > pi) phi <- phi - 2*pi
  if (phi > pi/2) phi <- pi - phi
  if (phi < -pi/2 ) phi <- -(phi+pi)  

  if (is.null(P)) { ## get plotting information...
    if (!x$plot.me) return(NULL) ## shouldn't or can't plot
    ## get basic plot data 
    raw <- data[x$term]
    if (rug) { ## need to project data onto plotting grid...
      raw <- lolaxy(lo=raw[[2]]*pi/180,la=raw[[1]]*pi/180,theta,phi)
    }

    m <- round(n2*1.5)
    ym <- xm <- seq(-1,1,length=m)
    gr <- expand.grid(x=xm,y=ym)
    r <- z <- gr$x^2+gr$y^2
    z[z>1] <- NA
    z <- sqrt(1-z)

    ## generate la, lo in plotting grid co-ordinates...
    ind <- !is.na(z) 
    r <- r[ind]
    la <- asin(gr$y[ind])
    lo <- cos(la)
    lo <- asin(gr$x[ind]/lo)

    um <- repole(lo,la,theta,phi)
 
    dat <- data.frame(la=um$la*180/pi,lo=um$lo*180/pi)
    names(dat) <- x$term
    if (x$by!="NA") dat[[x$by]] <- la*0+1    

    X <- PredictMat(x,dat)   # prediction matrix for this term

    ## fix lo for smooth contouring
    lo <- dat[[2]]
    ii <- lo <= -177
    lo[ii] <- lo[ii] <- 360 + lo[ii]
    ii <- lo < -165 & lo > -177 
    ii <- ii | (abs(dat[[1]])>80) 
    lo[ii] <- NA

    return(list(X=X,scale=FALSE,se=FALSE,raw=raw,xlab="",ylab="",main="",
                ind=ind,xm=xm,ym=ym,lo=lo,la=dat[[1]]))
  } else { ## do plot
    op <- par(pty="s",mar=c(0,0,0,0))
    m <- length(P$xm); zz <- rep(NA,m*m)
    if (scheme == 0) {
      col <- 1# "lightgrey 
      zz[P$ind] <- trans(P$fit+shift)
      image(P$xm,P$ym,matrix(zz,m,m),col=hcolors,axes=FALSE,xlab="",ylab="",...)
      if (rug) { 
        if (is.null(list(...)[["pch"]])) points(P$raw$x,P$raw$y,pch=".",...) else
        points(P$raw$x,P$raw$y,...)
      }
      zz[P$ind] <- P$la
      contour(P$xm,P$ym,matrix(zz,m,m),add=TRUE,levels=c(-8:8*10),col=col,...)
      zz[P$ind] <- P$lo
      contour(P$xm,P$ym,matrix(zz,m,m),add=TRUE,levels=c(-8:9*20),col=col,...)
      zz[P$ind] <- P$fit
      contour(P$xm,P$ym,matrix(zz,m,m),add=TRUE,col=contour.col,...)
    } else if (scheme == 1) {
      col <- 1 
      zz[P$ind] <- trans(P$fit+shift)
      contour(P$xm,P$ym,matrix(zz,m,m),col=1,axes=FALSE,xlab="",ylab="",...) 
      if (rug) { 
        if (is.null(list(...)[["pch"]])) points(P$raw$x,P$raw$y,pch=".",...) else
        points(P$raw$x,P$raw$y,...)
      }
      zz[P$ind] <- P$la
      contour(P$xm,P$ym,matrix(zz,m,m),add=TRUE,levels=c(-8:8*10),col=col,lty=2,...)
      zz[P$ind] <- P$lo
      contour(P$xm,P$ym,matrix(zz,m,m),add=TRUE,levels=c(-8:9*20),col=col,lty=2,...)
      theta <- seq(-pi/2,pi/2,length=200)
      x <- sin(theta);y <- cos(theta)
      x <- c(x,x[200:1]);y <- c(y,-y[200:1])
      lines(x,y)
    } 
    par(op)
  }
}`

const rtdal004324Source0011 = `poly2 <- function(x,col) {
## let x be a 2 col matrix defining some polygons. 
## Different closed loop sections are separated by
## NA rows. This routine assumes that loops nested within 
## other loops are holes (further nesting gives and island 
## in hole, etc). Holes are left unfilled.
## The first polygon should not be a hole.
  ind <- (1:nrow(x))[is.na(rowSums(x))] ## where are the splits?
  if (length(ind)==0|| ind[1]==nrow(x)) polygon(x,col=col,border="black") else {
    base <- x[1,]
    xf <- x
    xf[ind,1] <- base[1]
    xf[ind,2] <- base[2]
    if (!is.na(col)) polygon(xf,col=col,border=NA,fillOddEven=TRUE)
    polygon(x,border="black")
  }
}`

const rtdal004324Source0012 = `polys.plot <- function(pc,z=NULL,scheme="heat",lab="",...) { 
## pc is a list of polygons defining area boundaries
## pc[[i]] is the 2 col matrix of vertex co-ords for polygons defining 
## boundary of area i
## z gives the value associated with the area
  
  ## first find the axes ranges...

  for (i in 1:length(pc)) {
    yr <- range(pc[[i]][,2],na.rm=TRUE)
    xr <- range(pc[[i]][,1],na.rm=TRUE)

    if (i==1) {
      ylim <- yr
      xlim <- xr
    } else {
      if (yr[1]<ylim[1]) ylim[1] <- yr[1]
      if (yr[2]>ylim[2]) ylim[2] <- yr[2]
      if (xr[1]<xlim[1]) xlim[1] <- xr[1]
      if (xr[2]>xlim[2]) xlim[2] <- xr[2]
    }
  } ## end of axes range loop

  mar <- par("mar");
  oldpar <- par(mar=c(2,mar[2],2,1)) 

  if (is.null(z)) { ## no z value, no shading, no scale, just outlines...
     plot(0,0,ylim=ylim,xlim=xlim,xaxt="n",yaxt="n",type="n",bty="n",ylab=lab,xlab="",...)
     for (i in 1:length(pc)) { 
       poly2(pc[[i]],col=NA)
     }
  } else {
    
    nz <- names(z)
    npc <- names(pc)
    if (!is.null(nz)&&!is.null(npc)) { ## may have to re-order z into pc order.
      if (all.equal(sort(nz),sort(npc))!=TRUE) stop("names of z and pc must match")
      z <- z[npc]
    } 

    xmin <- xlim[1]
    xlim[1] <- xlim[1] - .1 * (xlim[2]-xlim[1]) ## allow space for scale

    n.col <- 100
    if (scheme=="heat") scheme <- heat.colors(n.col+1) else 
    scheme <- gray(0:n.col/n.col)
   
    zlim <- range(pretty(z))

    ## Now want a grey or color scale up the lhs of plot
    ## first scale the y range into the z range for plotting 

    for (i in 1:length(pc)) pc[[i]][,2] <- zlim[1] + 
         (zlim[2]-zlim[1])*(pc[[i]][,2]-ylim[1])/(ylim[2]-ylim[1])
  
    ylim <- zlim
    plot(0,0,ylim=ylim,xlim=xlim,type="n",xaxt="n",bty="n",xlab="",ylab=lab,...)
    for (i in 1:length(pc)) {
      coli <- round((z[i] - zlim[1])/(zlim[2]-zlim[1])*n.col)+1    
      poly2(pc[[i]],col=scheme[coli])
    }
  
    ## now plot the scale bar...

    xmin <- min(c(axTicks(1),xlim[1]))
    dx <- (xlim[2]-xlim[1])*.05
    x0 <- xmin-2*dx
    x1 <- xmin+dx

    dy <- (ylim[2]-ylim[1])/n.col 
    poly <- matrix(c(x0,x0,x1,x1,ylim[1],ylim[1]+dy,ylim[1]+dy,ylim[1]),4,2)
    for (i in 1:n.col) {
      polygon(poly,col=scheme[i],border=NA)
      poly[,2] <- poly[,2] + dy
    }
    poly <- matrix(c(x0,x0,x1,x1,ylim[1],ylim[2],ylim[2],ylim[1]),4,2)
    polygon(poly,border="black")
  }
  par(oldpar)
}`

const rtdal004324Source0013 = `plot.mrf.smooth <- function(x,P=NULL,data=NULL,label="",
                     partial.resids=FALSE,rug=TRUE,se=TRUE,scale=-1,n=100,n2=40,n3=3,
                     theta=30,phi=30,jit=FALSE,xlab=NULL,ylab=NULL,main=NULL,
                     ylim=NULL,xlim=NULL,too.far=0.1,shade.col="gray80",
                     shift=0,trans=I,by.resids=FALSE,scheme=0,...) {
## plot method function for mrf.smooth terms, depends heavily on polys.plot, above
  if (is.null(P)) { ## get plotting information...
    if (!x$plot.me||is.null(x$xt$polys)) return(NULL) ## shouldn't or can't plot
    ## get basic plot data 
    raw <- data[x$term][[1]]
    dat <- data.frame(x=factor(names(x$xt$polys),levels=levels(x$knots)))
    names(dat) <- x$term
    x$by <- "NA"
    X <- PredictMat(x,dat)   # prediction matrix for this term
    if (is.null(xlab)) xlabel<- "" else xlabel <- xlab
    if (is.null(ylab)) ylabel <- "" else ylabel <- ylab
    return(list(X=X,scale=FALSE,se=FALSE,raw=raw,xlab=xlabel,ylab=ylabel,
             main=label))
    } else { ## do plot
      if (scheme==0) scheme <- "heat" else scheme <- "grey"
      polys.plot(x$xt$polys,trans(P$fit+shift),scheme=scheme,lab=P$main,...)
    }

}`

const rtdal004324Source0014 = `plot.sz.interaction <- function(x,P=NULL,data=NULL,label="",
                     partial.resids=FALSE,rug=TRUE,se=TRUE,scale=-1,n=100,n2=40,n3=3,
                     theta=30,phi=30,jit=FALSE,xlab=NULL,ylab=NULL,main=NULL,
                     ylim=NULL,xlim=NULL,too.far=0.1,shade.col="gray80",
                     shift=0,trans=I,by.resids=FALSE,scheme=0,...) {
## plot method for factor smooth interactions designed for models such as s(x) + s(fac,x) where
## the factor level dependent smooths are strictly deviations from the main effect smooth.

  nf2i <- function(nf,i) {
    k <- length(nf)
    kk <- rep(0,k)
    i <- i-1
    for (j in k:1) {
      kk[j] <- i %% nf[j] + 1
      i <- i %/% nf[j]
    }
    kk
  } ## nf2i

  if (is.null(P)) { ## get plotting info
    if (x$base$dim!=1) return(NULL) ## no method for base smooth dim > 1
    raw <- data[x$base$term][[1]]
    xx <- seq(min(raw),max(raw),length=n) # generate x sequence for prediction
    nf <- unlist(lapply(x$flev,length)) ## levels per grouping factor
    dat <- data.frame(rep(xx,prod(nf)))
    k <- length(x$flev) ## number of factors
    for (i in 1:k) {
      re <- if (i<k) prod(nf[(i+1):k]) else 1
      rs <- if (i>1) prod(nf[1:(i-1)]) else 1
      dat[,i+1] <- factor(rep(rep(x$flev[[i]],each=re*n),rs),levels=x$flev[[i]])
    }
    names(dat) <- c(x$base$term,x$fterm)  
    if (x$by!="NA") {        # deal with any by variables
      dat[[x$by]] <- rep(1,n)
    }
    X <- PredictMat(x,dat)
    if (is.null(xlab)) xlabel <- x$base$term else xlabel <- xlab
    if (is.null(ylab)) ylabel <- label else ylabel <- ylab
    clev <- if (is.numeric(se)) se else .95
    return(list(X=X,scale=TRUE,se=TRUE,clev=clev,raw=raw,xlab=xlabel,ylab=ylabel,
             main="",x=xx,n=n,nf=nf))
  } else { ## produce the plot
    nft <- prod(P$nf) ## total number of curves
    if (scheme!=1) {
      kol <- hcl.colors(nft,palette = "viridis", alpha = .33) ## CI
      lkol <- hcl.colors(nft,palette = "viridis", alpha = .66) ## mode
      tkol <- hcl.colors(nft,palette = "viridis", alpha = 1) ## label
    }  
    xlim <- range(P$x);dx <- xlim[2]-xlim[1]
    xt <- xlim[1] + (1:nft-.5)*dx/nft ## text locations
    ind <- 1:P$n; mind <- P$n:1
    
    if(is.null(ylim)) ylim <- trans(range(c(P$ll[,1],P$ul[,1]))+shift)

    plot(P$x[ind],trans(P$fit[ind]+shift),ylim=ylim,xlab=P$xlab,ylab=P$ylab,type="n",...)

    nfac <- length(P$nf) ## number of factors
    kk <- rep(0,nfac) ## factor level index vector
    if (scheme==1) {
      for (i in 1:nft) {
        ul <- trans(P$ul[ind,1]+shift)
        ll <- trans(P$ll[ind,1] +shift)
	lines(P$x,ul,col="grey",lty=i);lines(P$x,ll,col="grey",lty=i)
        ii <- P$x < xt[i] - dx/30
	yt <- approx(P$x,P$fit[ind],xt[i])$y
        lines(P$x[ii],(P$fit[ind])[ii],lty=i,lwd=2)
        text(xt[i],yt,paste(nf2i(P$nf,i),collapse="."))
        ii <- P$x > xt[i] + dx/30
        lines(P$x[ii],(P$fit[ind])[ii],lty=i,lwd=2)
        ind <- ind + P$n; mind <- mind + P$n
      }	
    } else {
      for (i in 1:nft) {
        ul <- trans(P$ul[ind,1] +shift)
        ll <- trans(P$ll[mind,1] +shift)
        polygon(c(P$x,P$x[P$n:1]),c(ul,ll),col=kol[i],border=kol[i])
        yt <- approx(P$x,P$fit[ind],xt[i])$y
        ii <- P$x < xt[i] - dx/30
        lines(P$x[ii],(P$fit[ind])[ii],col=lkol[i])
        text(xt[i],yt,paste(nf2i(P$nf,i),collapse="."),col=tkol[i])
        ii <- P$x > xt[i] + dx/30
        lines(P$x[ii],(P$fit[ind])[ii],col=lkol[i])
        ind <- ind + P$n; mind <- mind + P$n
      }
    }  
  }
}`

const rtdal004324Source0015 = `plot.fs.interaction <- function(x,P=NULL,data=NULL,label="",
                     partial.resids=FALSE,rug=TRUE,se=TRUE,scale=-1,n=100,n2=40,n3=3,
                     theta=30,phi=30,jit=FALSE,xlab=NULL,ylab=NULL,main=NULL,
                     ylim=NULL,xlim=NULL,too.far=0.1,shade.col="gray80",
                     shift=0,trans=I,by.resids=FALSE,scheme=0,...) {
## plot method for simple smooth factor interactions...
  if (is.null(P)) { ## get plotting info
    if (x$dim!=1) return(NULL) ## no method for base smooth dim > 1
    raw <- data[x$base$term][[1]]
    xx <- seq(min(raw),max(raw),length=n) # generate x sequence for prediction
    nf <- length(x$flev)
    fac <- rep(x$flev,rep(n,nf))
    dat <- data.frame(fac,xx,stringsAsFactors=TRUE)
    names(dat) <- c(x$fterm,x$base$term)  
    if (x$by!="NA") {        # deal with any by variables
      dat[[x$by]] <- rep(1,n)
    }
    X <- PredictMat(x,dat)
    if (is.null(xlab)) xlabel <- x$base$term else xlabel <- xlab
    if (is.null(ylab)) ylabel <- label else ylabel <- ylab
    return(list(X=X,scale=TRUE,se=FALSE,raw=raw,xlab=xlabel,ylab=ylabel,
             main="",x=xx,n=n,nf=nf))
  } else { ## produce the plot
    ind <- 1:P$n
    if(is.null(ylim)) ylim <- trans(range(P$fit)+shift) 
    plot(P$x[ind],trans(P$fit[ind]+shift),ylim=ylim,xlab=P$xlab,ylab=P$ylab,type="l",...)
    if (P$nf>1) for (i in 2:P$nf) {
      ind <- ind + P$n
      if (scheme==0) lines(P$x,trans(P$fit[ind]+shift),lty=i,col=i) else 
      lines(P$x,trans(P$fit[ind]+shift),lty=i)
    }
  }
}`

const rtdal004324Source0016 = "plot.mgcv.smooth <- function(x,P=NULL,data=NULL,label=\"\",\n                     partial.resids=FALSE,rug=TRUE,se=TRUE,scale=-1,n=100,n2=40,n3=3,\n                     theta=30,phi=30,jit=FALSE,xlab=NULL,ylab=NULL,main=NULL,\n                     ylim=NULL,xlim=NULL,too.far=0.1,shade.col=\"gray80\",\n                     shift=0,trans=I,by.resids=FALSE,scheme=0,hcolors=heat.colors(50),\n                     contour.col=4,deriv=FALSE,...) {\n## default plot method for smooth objects `x' inheriting from \"mgcv.smooth\"\n## `x' is a smooth object, usually part of a `gam' fit. It has an attribute\n##     'coefficients' containing the coefs for the smooth, but usually these\n##     are not needed.\n## Usually this function is called twice. First to set up P, then to compute the\n## actual plot information including standard error bands, and then to actually \n## plot... \n## `P' is a list of plot data. \n##     If `P' is NULL (first call) then the routine should compute some of this plot data\n##     and return without plotting...  \n##     * X the matrix mapping the smooth's coefficients to the values at\n##         which the smooth must be computed for plotting.\n##     * The values against which to plot.\n##     * `exclude' indicates rows of X%*%p to set to NA for plotting -- NULL for none.\n##     * se TRUE if plotting of the term can use standard error information.\n##     * clev - the confidence level(s) of confidence bands\n##     * scale TRUE if the term should be considered by plot.gam if a common\n##             y scale is required.\n##     * any raw data information.\n##     * axis labels and plot titles \n##     As an alternative, P may contain a 'fit' field directly, in which case the \n##     very little processing is done outside the routine, except for partial residual\n##     computations.\n##     Alternatively return P as NULL if x should not be plotted.\n##     If P is not NULL (second call) it will contain the following...\n##     * fit - the values for plotting \n##     * ll,ul - lower and upper confidence limits (earlier cols are higher levels)\n##     * the values against which to plot\n##     * any raw data information\n##     * any partial.residuals \n## `data' is a data frame containing the raw data for the smooth, usually the \n##        model.frame of the fitted gam. Can be NULL if P is not NULL.\n## `label' is the term label, usually something like e.g. `s(x,12.34)'.\n## Note that if ylim is supplied it should not be transformed using trans and shift.\n#############################\n\n  sp.contour <- function(x,y,z,ll,ul,xlab=\"\",ylab=\"\",zlab=\"\",titleOnly=FALSE,\n               se.plot=TRUE,clev,trans=I,shift=0,...) {\n  ## function for contouring 2-d smooths with 1 s.e. limits\n    gap<-median((ul-ll)/2,na.rm=TRUE)  \n    zr<-max(trans(ul+shift),na.rm=TRUE)-min(trans(ll+shift),na.rm=TRUE) # plotting range  \n    n<-10  \n    while (n>1 && zr/n<2.5*gap) n<-n-1    \n    zrange<-c(min(trans(ll+shift),na.rm=TRUE),max(trans(ul+shift),na.rm=TRUE))  \n    zlev<-pretty(zrange,n)  ## ignore codetools on this one  \n    yrange<-range(y);yr<-yrange[2]-yrange[1]  \n    xrange<-range(x);xr<-xrange[2]-xrange[1]  \n    ypos<-yrange[2]+yr/10\n    args <- as.list(substitute(list(...)))[-1]\n    args$x <- substitute(x);args$y <- substitute(y)\n    args$type=\"n\";args$xlab<-args$ylab<-\"\";args$axes<-FALSE\n    do.call(\"plot\",args)\n\n    cs<-(yr/10)/strheight(zlab);if (cs>1) cs<-1 # text scaling based on height  \n  \n    tl<-strwidth(zlab);  \n    if (tl*cs>3*xr/10) cs<-(3*xr/10)/tl  \n    args <- as.list(substitute(list(...)))[-1]\n    n.args <- names(args)\n    zz <- trans(z+shift) ## ignore codetools for this\n    args$x<-substitute(x);args$y<-substitute(y);args$z<-substitute(zz)\n    if (!\"levels\"%in%n.args) args$levels<-substitute(zlev)\n    if (!\"lwd\"%in%n.args) args$lwd<-2\n    if (!\"labcex\"%in%n.args) args$labcex<-cs*.65\n    if (!\"axes\"%in%n.args) args$axes <- FALSE\n    if (!\"add\"%in%n.args) args$add <- TRUE\n    do.call(\"contour\",args)\n  \n    if (is.null(args$cex.main)) cm <- 1 else cm <- args$cex.main\n    if (titleOnly)  title(zlab,cex.main=cm) else {\n      xpos<-xrange[1]+3*xr/10  \n      xl<-c(xpos,xpos+xr/10); yl<-c(ypos,ypos)   \n      lines(xl,yl,xpd=TRUE,lwd=args$lwd)  \n      text(xpos+xr/10,ypos,zlab,xpd=TRUE,pos=4,cex=cs*cm,off=0.5*cs*cm)  \n    }\n    if  (is.null(args$cex.axis)) cma <- 1 else cma <- args$cex.axis\n    axis(1,cex.axis=cs*cma);axis(2,cex.axis=cs*cma);box();\n    if  (is.null(args$cex.lab)) cma <- 1 else cma <- args$cex.lab  \n    mtext(xlab,1,2.5,cex=cs*cma);mtext(ylab,2,2.5,cex=cs*cma)  \n    if (!\"lwd\"%in%n.args) args$lwd<-1\n    if (!\"lty\"%in%n.args) args$lty<-2\n    if (!\"col\"%in%n.args) args$col<-2\n    if (!\"labcex\"%in%n.args) args$labcex<-cs*.5\n    #zz <- trans(z-zse+shift)\n    zz <- trans(ll+shift)\n    args$z<-substitute(zz)\n\n    do.call(\"contour\",args)\n\n    alpha <- (1-clev)/2 \n\n    if (!titleOnly) {\n      xpos<-xrange[1]  \n      xl<-c(xpos,xpos+xr/10)#;yl<-c(ypos,ypos)  \n      lines(xl,yl,xpd=TRUE,lty=args$lty,col=args$col)\n      txt <- paste(\".\",strsplit(paste(round(alpha,3)),\".\",fixed=TRUE)[[1]][2],sep=\"\")\n      text(xpos+xr/10,ypos,txt,xpd=TRUE,pos=4,cex=cs*cm,off=0.5*cs*cm)  \n     # text(xpos+xr/10,ypos,paste(\"-\",round(se.mult),\"se\",sep=\"\"),xpd=TRUE,pos=4,cex=cs*cm,off=0.5*cs*cm)  \n    }\n\n    if (!\"lty\"%in%n.args) args$lty<-3\n    if (!\"col\"%in%n.args) args$col<-4\n    #zz <- trans(z + zse+shift)\n    zz <- trans(ul+shift)\n    args$z<-substitute(zz)\n    do.call(\"contour\",args)\n\n    alpha <- 1 - alpha\n\n    if (!titleOnly) {\n      xpos<-xrange[2]-xr/5  \n      xl<-c(xpos,xpos+xr/10);  \n      lines(xl,yl,xpd=TRUE,lty=args$lty,col=args$col)\n      txt <- paste(\".\",strsplit(paste(round(alpha,3)),\".\",fixed=TRUE)[[1]][2],sep=\"\")\n      text(xpos+xr/10,ypos,txt,xpd=TRUE,pos=4,cex=cs*cm,off=0.5*cs*cm)  \n      #text(xpos+xr/10,ypos,paste(\"+\",round(se.mult),\"se\",sep=\"\"),xpd=TRUE,pos=4,cex=cs*cm,off=0.5*cs*cm)  \n    }\n  }  ## end of sp.contour\n\n  if (is.null(P)) { ## get plotting information...\n    if (!x$plot.me||x$dim>4) return(NULL) ## shouldn't or can't plot\n    if (x$dim==1) { ## get basic plotting data for 1D terms \n      raw <- data[x$term][[1]]\n      if (is.null(xlim)) xx <- seq(min(raw),max(raw),length=n) else # generate x sequence for prediction\n      xx <- seq(xlim[1],xlim[2],length=n)\n      if (x$by!=\"NA\") {        # deal with any by variables\n        by<-rep(1,n);dat<-data.frame(x=xx,by=by)\n        names(dat)<-c(x$term,x$by)\n      } else { \n        dat<-data.frame(x=xx);names(dat) <- x$term\n      } ## prediction data.frame finished\n      X <- PredictMat(x,dat)   # prediction matrix for this term\n      if (deriv) {\n        eps <- diff(range(xx))*1e-7\n\tdat[[1]] <- dat[[1]] + eps\n\tX <- (PredictMat(x,dat) - X)/eps\n\tif (is.null(ylab)&&length(grep(\"(\",label,fixed=TRUE))) {\n          label2 <- strsplit(label,\"(\",fixed=TRUE)[[1]]\n          label <- paste(label2[1],\"'(\",label2[-1],sep=\"\")\n        }\n      }\n      if (is.null(xlab)) xlabel<- x$term else xlabel <- xlab\n      if (is.null(ylab)) ylabel <- label else ylabel <- ylab\n      if (is.null(xlim)) xlim <- range(xx)\n      clev <- if (is.numeric(se)) se else .95\n      if (scheme==2&&length(clev)<2) clev <- c(0.95,0.68)\n      if (scheme!=2) clev <- clev[1]\n      return(list(X=X,x=xx,scale=TRUE,se=as.logical(se[1]),raw=raw,xlab=xlabel,ylab=ylabel,\n             main=main,clev=clev,xlim=xlim))\n    } else if (x$dim==2) { ## basic plot data for 2D terms\n      xterm <- x$term[1]\n      if (is.null(xlab)) xlabel <- xterm else xlabel <- xlab\n      yterm <- x$term[2]\n      if (is.null(ylab)) ylabel <- yterm else ylabel <- ylab\n      raw <- data.frame(x=as.numeric(data[xterm][[1]]),\n                        y=as.numeric(data[yterm][[1]]))\n      n2 <- max(10,n2)\n      if (is.null(xlim)) xm <- seq(min(raw$x),max(raw$x),length=n2) else \n        xm <- seq(xlim[1],xlim[2],length=n2)\n      if (is.null(ylim)) ym <- seq(min(raw$y),max(raw$y),length=n2) else\n        ym <- seq(ylim[1],ylim[2],length=n2)\n      xx <- rep(xm,n2)\n      yy <- rep(ym,rep(n2,n2))\n      if (too.far>0)\n      exclude <- exclude.too.far(xx,yy,raw$x,raw$y,dist=too.far) else\n      exclude <- rep(FALSE,n2*n2)\n      if (x$by!=\"NA\") {        # deal with any by variables\n        by <- rep(1,n2^2);dat <- data.frame(x=xx,y=yy,by=by)\n        names(dat) <- c(xterm,yterm,x$by)\n      } else { \n        dat<-data.frame(x=xx,y=yy);names(dat)<-c(xterm,yterm)\n      }  ## prediction data.frame complete\n      X <- PredictMat(x,dat)   ## prediction matrix for this term\n      if (is.null(main)) { \n        main <- label\n      }\n      if (is.null(ylim)) ylim <- range(ym) \n      if (is.null(xlim)) xlim <- range(xm)\n      clev <- if (is.numeric(se)) se else .68\n      return(list(X=X,x=xm,y=ym,scale=FALSE,se=TRUE,raw=raw,xlab=xlabel,ylab=ylabel,\n             main=main,clev=clev,ylim=ylim,xlim=xlim,exclude=exclude))\n    } else { ## basic plot data for 3 or 4 d terms\n      vname <- x$term\n      ## if the smooth has margins and one is 2D then set that as the \n      ## term for 2D plotting, rather than conditioning....\n      if (!is.null(x$margin)) {\n        for (i in 1:length(x$margin)) if (x$margin[[i]]$dim==2) {\n          vname <- x$margin[[i]]$term ## these are the variables to 2d plot\n          vname <- c(vname,x$term[!x$term%in%vname])\n          break;\n        }\n      }\n      ## ... so first 2 terms in vname are the vars to plot in 2D. \n      ## Now get the limits for plotting...\n      nv <- length(vname)\n      lo <- hi <- rep(0,nv)\n      for (i in 1:length(vname)) {\n        xx <- data[vname[i]][[1]] \n        lo[i] <- min(xx);hi[i] <- max(xx)\n      } \n      nc <- nr <- n3 ## set number cols and rows of plot\n      m <- n2 ## 2d plotting grid side\n      x1 <- seq(lo[1],hi[1],length=m)\n      x2 <- seq(lo[2],hi[2],length=m)\n      if (nv==3) {\n        x3 <- seq(lo[3],hi[3],length=nr*nc)\n        dat <- cbind(rep(x1,m*nr*nc),\n           rep(rep(x2,each=m*nr),nc),\n           x3[rep(rep((1:nr-1)*nc,each=m),m*nc) + rep(1:nc,each=m*m*nr)])\n      } else {\n        x3 <- seq(lo[3],hi[3],length=nr)\n        x4 <- seq(lo[4],hi[4],length=nc)\n        dat <- cbind(rep(x1,m*nr*nc),\n             rep(rep(x2,each=m*nr),nc),\n             rep(rep(x3,each=m),m*nc),\n             rep(x4,each=m*m*nr))\n      } ## 4D term end\n      if (x$by!=\"NA\") {\n        dat <- data.frame(cbind(dat,1))\n        names(dat) <- c(vname,x$by)\n      } else {\n        dat <- data.frame(dat)\n        names(dat) <- vname\n      }\n      X <- PredictMat(x,dat)   ## prediction matrix for this term\n      exclude <- if (too.far<=0) rep(FALSE,nrow(X)) else\n      exclude.too.far(dat[,1],dat[,2],data[vname[1]][[1]],data[vname[2]][[1]],dist=too.far)\n      if (is.null(main)) { \n        main <- label\n      }\n      return(list(X=X,scale=FALSE,se=FALSE,m=m,nc=nc,nr=nr,lo=lo,hi=hi,vname=vname,\n             main=main,exclude=exclude))\n    } ## end of 3/4 D case\n  } else { ## produce plot\n    if (P$plot.ci) { ## produce CI's\n      if (x$dim==1) { \n        #ul <- P$fit + P$se ## upper CL\n        #ll <- P$fit - P$se ## lower CL\n\tul <- P$ul[,1];ll <- P$ll[,1]\n        if (scale==0&&is.null(ylim)) { ## get scale \n          ylimit<-c(min(ll),max(ul))\n          if (partial.resids) { \n            max.r <- max(P$p.resid,na.rm=TRUE)\n            if ( max.r> ylimit[2]) ylimit[2] <- max.r\n            min.r <-  min(P$p.resid,na.rm=TRUE)\n            if (min.r < ylimit[1]) ylimit[1] <- min.r\n          }\n        }\n        ylimit <- if (is.null(ylim)) ylimit <- trans(ylimit + shift) else ylim\n         \n        ## plot the smooth...\n        \n        if (scheme == 2) {\n          plot(P$x,trans(P$fit+shift),type=\"n\",xlab=P$xlab,ylim=ylimit,\n                 xlim=P$xlim,ylab=P$ylab,main=P$main,...)\n          dx <- diff(P$xlim); dy <- diff(ylimit)\n          xa <- axis(1);ya <- axis(2)\n          rect(P$xlim[1]-dx*.1,ylimit[1]-dy*.1,P$xlim[2]+dx*.1,ylimit[2]+dy*.1,col=\"lightgrey\")\n          abline(v=xa,col=\"white\");abline(h=ya,col=\"white\")\n          #rgb.col <- rgb(0,.2,.8,alpha=.5)\n\t  if (length(shade.col)<2) shade.col <- c(rgb(0,.2,.8,alpha=.5),\"blue\")\n          polygon(c(P$x,P$x[n:1],P$x[1]),\n                    trans(c(ul,ll[n:1],ul[1])+shift),col = shade.col[1],border = NA) \n          #ul <- P$fit + P$se/2 ## upper CL\n          #ll <- P$fit - P$se/2 ## lower CL\n\t  ul <- P$ul[,2];ll <- P$ll[,2]\n          polygon(c(P$x,P$x[n:1],P$x[1]),\n                    trans(c(ul,ll[n:1],ul[1])+shift),col = shade.col[2],border = NA) \n          lines(P$x,trans(P$fit+shift),...)\n        } else if (scheme==1) { \n          plot(P$x,trans(P$fit+shift),type=\"n\",xlab=P$xlab,ylim=ylimit,\n                 xlim=P$xlim,ylab=P$ylab,main=P$main,...)\n          polygon(c(P$x,P$x[n:1],P$x[1]),\n                    trans(c(ul,ll[n:1],ul[1])+shift),col = shade.col,border = NA)\n          lines(P$x,trans(P$fit+shift),...)\n        } else { ## ordinary plot \n          plot(P$x,trans(P$fit+shift),type=\"l\",xlab=P$xlab,ylim=ylimit,xlim=P$xlim,\n                 ylab=P$ylab,main=P$main,...)\n          if (is.null(list(...)[[\"lty\"]])) { \n            lines(P$x,trans(ul+shift),lty=2,...)\n            lines(P$x,trans(ll+shift),lty=2,...)\n          } else { \n            lines(P$x,trans(ul+shift),...)\n            lines(P$x,trans(ll+shift),...)\n          }\n        } ## ... smooth plotted\n       \n        if (partial.resids&&(by.resids||x$by==\"NA\")) { ## add any partial residuals\n          if (length(P$raw)==length(P$p.resid)) {\n            if (is.null(list(...)[[\"pch\"]]))\n            points(P$raw,trans(P$p.resid+shift),pch=\".\",...) else\n            points(P$raw,trans(P$p.resid+shift),...) \n          } else {\n            warning(\"Partial residuals do not have a natural x-axis location for linear functional terms\")\n          }\n        } ## partial residuals finished \n\t \n        if (rug) { \n          if (jit) rug(jitter(as.numeric(P$raw)),...)\n          else rug(as.numeric(P$raw),...)\n\t} ## rug plot done\n\n      } else if (x$dim==2) { \n        P$fit[P$exclude] <- NA\n        if (scheme == 1) { ## perspective plot \n          persp(P$x,P$y,matrix(trans(P$fit+shift),n2,n2),xlab=P$xlab,ylab=P$ylab,\n                  zlab=P$main,ylim=P$ylim,xlim=P$xlim,theta=theta,phi=phi,...)\n        } else if (scheme==2||scheme==3) {\n          if (scheme==3) hcolors <- grey(0:50/50)\n          image(P$x,P$y,matrix(trans(P$fit+shift),n2,n2),xlab=P$xlab,ylab=P$ylab,\n                  main=P$main,xlim=P$xlim,ylim=P$ylim,col=hcolors,...)\n          contour(P$x,P$y,matrix(trans(P$fit+shift),n2,n2),add=TRUE,col=contour.col,...)\n          if (rug) {  \n            if (is.null(list(...)[[\"pch\"]])) points(P$raw$x,P$raw$y,pch=\".\",...) else\n            points(P$raw$x,P$raw$y,...)\n          }\n        } else { ## contour plot with error contours\n          sp.contour(P$x,P$y,matrix(P$fit,n2,n2),matrix(P$ll,n2,n2),matrix(P$ul,n2,n2),\n                     xlab=P$xlab,ylab=P$ylab,zlab=P$main,titleOnly=!is.null(main),\n                     clev=P$clev,trans=trans,shift=shift,...)\n          if (rug) { \n            if (is.null(list(...)[[\"pch\"]]))\n            points(P$raw$x,P$raw$y,pch=\".\",...) else\n            points(P$raw$x,P$raw$y,...) \n          }\n        } ## contour plot done \n      } else if (x$dim<5) {\n        if (scheme==1) hcolors <- grey(0:50/50)\n        md.plot(P$fit,P$nr,P$nc,P$m,P$vname,P$lo,P$hi,hcolors=hcolors,scheme=scheme,P$main,...)\n      } else { \n         warning(\"no automatic plotting for smooths of more than two variables\")\n      }\n    } else { ## no CI's\n      if (x$dim==1) { \n        if (scale==0&&is.null(ylim)) { \n          if (partial.resids) ylimit <- range(P$p.resid,na.rm=TRUE) else ylimit <-range(P$fit)\n        }\n        ylimit <- if (is.null(ylim)) ylimit <- trans(ylimit + shift) else ylim\n        \n        plot(P$x,trans(P$fit+shift),type=\"l\",xlab=P$xlab,\n             ylab=P$ylab,ylim=ylimit,xlim=P$xlim,main=P$main,...)\n        if (rug) { \n          if (jit) rug(jitter(as.numeric(P$raw)),...)\n          else rug(as.numeric(P$raw),...) \n        }\n        if (partial.resids&&(by.resids||x$by==\"NA\")) { \n          if (is.null(list(...)[[\"pch\"]]))\n          points(P$raw,trans(P$p.resid+shift),pch=\".\",...) else\n          points(P$raw,trans(P$p.resid+shift),...)\n        }\n      } else if (x$dim==2) { \n        P$fit[P$exclude] <- NA\n        if (!is.null(main)) P$title <- main\n        if (scheme==1) { \n          persp(P$x,P$y,matrix(trans(P$fit+shift),n2,n2),xlab=P$xlab,ylab=P$ylab,\n                          zlab=P$main,theta=theta,phi=phi,xlim=P$xlim,ylim=P$ylim,...)\n        } else if (scheme==2||scheme==3) {\n          if (scheme==3) hcolors <- grey(0:50/50)\n          image(P$x,P$y,matrix(trans(P$fit+shift),n2,n2),xlab=P$xlab,ylab=P$ylab,\n                  main=P$main,xlim=P$xlim,ylim=P$ylim,col=hcolors,...)\n          contour(P$x,P$y,matrix(trans(P$fit+shift),n2,n2),add=TRUE,col=contour.col,...)\n          if (rug) {  \n            if (is.null(list(...)[[\"pch\"]])) points(P$raw$x,P$raw$y,pch=\".\",...) else\n            points(P$raw$x,P$raw$y,...)\n          }\n        } else { \n          contour(P$x,P$y,matrix(trans(P$fit+shift),n2,n2),xlab=P$xlab,ylab=P$ylab,\n                  main=P$main,xlim=P$xlim,ylim=P$ylim,...)\n          if (rug) {  \n            if (is.null(list(...)[[\"pch\"]])) points(P$raw$x,P$raw$y,pch=\".\",...) else\n            points(P$raw$x,P$raw$y,...)\n          }\n        }  \n      } else if (x$dim<5) {\n        if (scheme==1) hcolors <- grey(0:50/50)\n        md.plot(P$fit,P$nr,P$nc,P$m,P$vname,P$lo,P$hi,hcolors=hcolors,scheme=scheme,P$main,...)\n      } else { \n        warning(\"no automatic plotting for smooths of more than four variables\")\n      }\n    } ## end of no CI code\n  } ## end of plot production\n}"

const rtdal004324Source0017 = "md.plot <- function(f,nr,nc,m,vname,lo,hi,hcolors,scheme,main,...) {\n## multi-dimensional term plotter, called from plot.mgcv.smooth for\n## 3 and 4 dimensional terms. \n## *f is the plot data. See `basic plot data for 3 or 4 d terms'\n##   in plot.mgcv.smooth for details of the packing conventions\n##   (f = X %*% coefs).\n## *nr and nc the number of rows and columns of plot panels\n## *m each panel is m by m\n## *vname contains the variable names\n## *lo and hi are the arrays of axis limits\n## *hcolors is the color palette for the image plot.\n## *scheme indicates b/w or color\n## *main is a title.\n  concol <- if (scheme==1) \"white\" else \"black\" \n  nv <- length(vname) \n  ## insert NA breaks to separate the panels within a plot...\n  f1 <- matrix(NA,nr*m+nr-1,nc*m)\n  ii <- rep(1:m,nr) + rep(0:(nr-1)*(m+1),each=m)\n  f1[ii,] <- f\n  f <- matrix(NA,nr*m+nr-1,nc*m+nc-1)\n  ii <- rep(1:m,nc) + rep(0:(nc-1)*(m+1),each=m)\n  f[,ii] <- f1\n  xx <- seq(0,1,length=ncol(f))\n  yy <- seq(0,1,length=nrow(f))\n  image(xx,yy,t(f),axes=FALSE,xlab=\"\",ylab=\"\",col=hcolors)\n  contour(xx,yy,t(f),add=TRUE,col=concol)\n  dl <- list(...)\n  c1 <- if (is.null(dl[[\"cex\"]])) 1 else dl[[\"cex\"]] \n  c2 <- if (is.null(dl[[\"cex.axis\"]])) .6 else dl[[\"cex.axis\"]]\n  c3 <- if (is.null(dl[[\"cex.lab\"]])) .9 else dl[[\"cex.lab\"]]\n  if (nv==4) { \n    x3 <- seq(lo[3],hi[3],length=nr)\n    x4 <- seq(lo[4],hi[4],length=nc)\n    mtext(vname[4],1,1.7,cex=c1*c3) ## x label\n    mtext(vname[3],2,1.7,cex=c1*c3) ## y label\n    at=(1:nc-.5)/nc\n    lab <- format(x4,digits=2)\n    for (i in 1:nc) mtext(lab[i],1,at=at[i],line=.5,cex=c1*c3)\n    at=(1:nr-.5)/nr\n    lab <- format(x3,digits=2)\n    for (i in 1:nr) mtext(lab[i],2,at=at[i],line=.5,cex=c1*c3)\n    ## now the 2d panel axes...\n    xr <- axisTicks(c(lo[2],hi[2]),log=FALSE,nint=4)\n    x0 <- ((nc-1)*(m+1)+1)/(nc*m+nc-1)\n    xt <- (xr-lo[2])/(hi[2]-lo[2])*(1-x0)+x0\n    axis(3,at=xt,labels=as.character(xr),cex.axis=c2,cex=c1)\n    xr <- axisTicks(c(lo[1],hi[1]),log=FALSE,nint=4)\n    x0 <- ((nr-1)*(m+1)+1)/(nr*m+nr-1)\n    xt <- (xr-lo[1])/(hi[1]-lo[1])*(1-x0)+x0\n    axis(4,at=xt,labels=as.character(xr),cex.axis=c2,cex=c1)\n    at <- (2*nc-3)/(2*nc) \n    mtext(vname[2],3,at=at,line=.5,cex=c1*c2)\n    at <- (2*nr-3)/(2*nr) \n    mtext(vname[1],4,at=at,line=.5,cex=c1*c2)\n    mtext(main,3,at=0,adj=0,line=1,cex=c1*c3)\n  } else {\n    x3 <- seq(lo[3],hi[3],length=nr*nc)\n    ## get pretty ticks\n    xr <- axisTicks(c(lo[2],hi[2]),log=FALSE,nint=4)\n    x0 <- (m-1)/(nc*m+nc-1)\n    xt <- (xr-lo[2])/(hi[2]-lo[2])*x0\n    axis(1,at=xt,labels=as.character(xr),cex.axis=c2,cex=c1)\n    mtext(vname[2],1,at=x0/2,line=2,cex=c1*c2)\n    xr <- axisTicks(c(lo[1],hi[1]),log=FALSE,nint=4)\n    x0 <- (m-1)/(nr*m+nr-1)\n    xt <- (xr-lo[1])/(hi[1]-lo[1])*x0\n    axis(2,at=xt,labels=as.character(xr),cex.axis=c2,cex=c1)\n    mtext(vname[1],2,at=x0/2,line=2,cex=c1*c2)\n    lab <- c(\"\",format(x3[-1],digits=2))\n    at=(1:nc-.5)/nc\n    for (i in 2:nc) mtext(lab[i],1,at=at[i],line=.5,cex=c1*c3)\n    mtext(parse(text=paste(vname[3],\"%->% \\\" \\\"\")),1,at=mean(at[2:nc]),line=2,cex=c1*c3)\n    ii <- ((nr-1)*nr+1):(nc*nr)\n    for (i in 1:nc) mtext(lab[ii[i]],3,at=at[i],line=.5,cex=c1*c3)\n    mtext(parse(text=paste(vname[3],\"%->% \\\" \\\"\")),3,at=mean(at),line=1.5,cex=c1*c3)\n    mtext(main,2,at=1/nr+0.5*(nr-1)/nr,line=1,cex=c1*c3)\n  }\n}"

const rtdal004324Source0018 = `plot.gam <- function(x,residuals=FALSE,rug=NULL,se=TRUE,pages=0,select=NULL,scale=-1,n=100,n2=40,n3=3,
                     theta=30,phi=30,jit=FALSE,xlab=NULL,ylab=NULL,main=NULL,ylim=NULL,xlim=NULL,
		     too.far=0.1,all.terms=FALSE,shade.col="gray80",shift=0,trans=I,seWithMean=FALSE,
		     unconditional=FALSE,by.resids=FALSE,scheme=0,deriv=FALSE,...)

# Create an appropriate plot for each smooth term of a GAM.....
# x is a gam object
# rug determines whether a rug plot should be added to each plot
# se determines whether CIs are to be added
# pages is the number of pages over which to split output - 0 implies that 
# graphic settings should not be changed for plotting
# scale -1 for same y scale for each plot
#        0 for different y scales for each plot
# n - number of x axis points to use for plotting each term
# n2 is the square root of the number of grid points to use for contouring
# 2-d terms.

{ ######################################
  ## Local function for producing labels
  ######################################

  sub.edf <- function(lab,edf) {
    ## local function to substitute edf into brackets of label
    ## labels are e.g. smooth[[1]]$label
    pos <- regexpr(":",lab)[1]
    if (pos<0) { ## there is no by variable stuff
      pos <- nchar(lab) - 1
      lab <- paste(substr(lab,start=1,stop=pos),",",round(edf,digits=2),")",sep="")
    } else {
      lab1 <- substr(lab,start=1,stop=pos-2)
      lab2 <- substr(lab,start=pos-1,stop=nchar(lab))
      lab <- paste(lab1,",",round(edf,digits=2),lab2,sep="")
    }
    lab
  } ## end of sub.edf


  #########################
  ## start of main function
  #########################

  if (is.null(rug)) rug <- if (nrow(x$model)>10000) FALSE else TRUE

  if (unconditional) {
    if (is.null(x$Vc)) warning("Smoothness uncertainty corrected covariance not available") else 
    x$Vp <- x$Vc ## cov matrix reset to full Bayesian
  }

  w.resid <- NULL
  if (length(residuals)>1) { # residuals supplied 
    if (length(residuals)==length(x$residuals)) 
    w.resid <- residuals else
    warning("residuals argument to plot.gam is wrong length: ignored")
    partial.resids <- TRUE
  } else partial.resids <- residuals # use working residuals or none

  m <- length(x$smooth) ## number of smooth terms

  if (length(scheme)==1) scheme <- rep(scheme,m)
  if (length(scheme)!=m) { 
    warn <- paste("scheme should be a single number, or a vector with",m,"elements")
    warning(warn)
    scheme <- rep(scheme[1],m)
  }

  ## array giving order of each parametric term...
  order <- if (is.list(x$pterms))  unlist(lapply(x$pterms,attr,"order")) else attr(x$pterms,"order")

  if (all.terms) # plot parametric terms as well
  n.para <- sum(order==1) # plotable parametric terms   
  else n.para <- 0 
 
#  if (se) { ## sort out CI widths for 1 and 2D
#    if (is.numeric(se)) se2.mult <- se1.mult <- se else { se1.mult <- 2;se2.mult <- 1} 
#    if (se1.mult<0) se1.mult<-0;if (se2.mult < 0) se2.mult <- 0
#  } else se1.mult <- se2.mult <-1
  if (is.numeric(se)) {
    se <- sort(se,decreasing = TRUE)
    if (any(se>=1)) se <- TRUE else if (any(se<=0)) se <- FALSE
  }

  if (se[1] && x$Vp[1,1] < 0) ## check that variances are actually available
  { se <- FALSE
    warning("No variance estimates available")
  }

  if (partial.resids) { ## getting information needed for partial residuals...
    if (is.null(w.resid)) { ## produce working resids if info available
      if (is.null(x$residuals)||is.null(x$weights)) partial.resids <- FALSE else {
        wr <- sqrt(x$weights)
        w.resid <- x$residuals*wr#/mean(wr) # weighted working residuals
      }
    }
    if (partial.resids) fv.terms <- predict(x,type="terms") ## get individual smooth effects
  }

  pd <- list(); ## plot data list
  i <- 1 # needs a value if no smooths, but parametric terms ...

  ##################################################
  ## First the loop to get the data for the plots...
  ##################################################

  if (m>0) for (i in 1:m) { ## work through smooth terms
    first <- x$smooth[[i]]$first.para
    last <- x$smooth[[i]]$last.para
    edf <- sum(x$edf[first:last]) ## Effective DoF for this term
    term.lab <- sub.edf(x$smooth[[i]]$label,edf)
    #P <- plot(x$smooth[[i]],P=NULL,data=x$model,n=n,n2=n2,xlab=xlab,ylab=ylab,too.far=too.far,label=term.lab,
    #          se1.mult=se1.mult,se2.mult=se2.mult,xlim=xlim,ylim=ylim,main=main,scheme=scheme[i],...)
    attr(x$smooth[[i]],"coefficients") <- x$coefficients[first:last]   ## relevent coefficients
    P <- plot(x$smooth[[i]],P=NULL,data=x$model,partial.resids=partial.resids,rug=rug,se=se,scale=scale,n=n,n2=n2,n3=n3,
                     theta=theta,phi=phi,jit=jit,xlab=xlab,ylab=ylab,main=main,label=term.lab,
                     ylim=ylim,xlim=xlim,too.far=too.far,shade.col=shade.col,shift=shift,trans=trans,
                     by.resids=by.resids,scheme=scheme[i],deriv=deriv,...)

    if (is.null(P)) pd[[i]] <- list(plot.me=FALSE) else if (is.null(P$fit)) {
      p <- x$coefficients[first:last]   ## relevent coefficients 
      offset <- attr(P$X,"offset")      ## any term specific offset
      ## get fitted values ....
      if (is.null(offset)) P$fit <- P$X%*%p else P$fit <- P$X%*%p + offset 
      if (!is.null(P$exclude)) P$fit[P$exclude] <- NA
      if (se[1] && P$se && is.null(x$bs)) { ## get standard errors for fit
        ## test whether mean variability to be added to variability (only for centred terms)
        if (seWithMean && !is.null( attr(x$smooth[[i]],"nCons")) && attr(x$smooth[[i]],"nCons")>0) {
          if (length(x$cmX) < ncol(x$Vp)) x$cmX <- c(x$cmX,rep(0,ncol(x$Vp)-length(x$cmX)))
          if (seWithMean==2) x$cmX[-(1:x$nsdf)] <- 0 ## variability of fixed effects mean only
          X1 <- matrix(x$cmX,nrow(P$X),ncol(x$Vp),byrow=TRUE)
          meanL1 <- x$smooth[[i]]$meanL1
          if (!is.null(meanL1)) X1 <- X1 / meanL1
          X1[,first:last] <- P$X
          lpi <- attr(x$formula,"lpi")
          if (is.null(lpi)) se.fit <- sqrt(pmax(0,rowSums(as(X1%*%x$Vp,"matrix")*X1))) else {
            ii <- rep(0,0) ## only include constant uncertainty from relevant linear predictors  
            for (q in 1:length(lpi)) if (any(first:last%in%lpi[[q]])) ii <- c(ii,lpi[[q]])
            se.fit <- sqrt(pmax(0,rowSums(as(X1[,ii]%*%x$Vp[ii,ii],"matrix")*X1[,ii])))
          }
	} else { ## se in centred (or anyway unconstained) space only
	  if (seWithMean && is.null( attr(x$smooth[[i]],"nCons"))) warning("seWithMean unavailable")
	  se.fit <- sqrt(pmax(0,rowSums(as(P$X%*%x$Vp[first:last,first:last,drop=FALSE],"matrix")*P$X)))
        }
        if (!is.null(P$exclude)) se.fit[P$exclude] <- NA
      } ## standard errors for fit completed
      if (partial.resids) { P$p.resid <- fv.terms[,length(order)+i] + w.resid }
      if (se[1] && P$se) {
        se.mult <- if (is.null(P$clev)) P$se.mult else -qnorm((1-P$clev)/2)
	if (!is.null(x$bs))  {
	  ff <- P$X%*%x$bs[first:last,]
	  delta <- if (is.null(attr(x$bs,"svar.only"))) 0 else
	           mean(sqrt(pmax(0,rowSums(as(P$X%*%x$Vp[first:last,first:last,drop=FALSE],"matrix")*P$X)))-
	           sqrt(pmax(0,rowSums(as(P$X%*%x$Ve[first:last,first:last,drop=FALSE],"matrix")*P$X))))
	}
	P$ll <- P$ul <- matrix(0,length(P$fit),length(se.mult))
	for (j in 1:length(se.mult)) if (is.null(x$bs)) {
           P$ll[,j] <- P$fit - se.fit * se.mult[j]
	   P$ul[,j] <- P$fit + se.fit * se.mult[j]
        } else {
	   alpha <- (1-P$clev[j])/2
           P$ll[,j] <- apply(ff,1,quantile,probs=alpha) - delta*se.mult[j]
	   P$ul[,j] <- apply(ff,1,quantile,probs=1-alpha) + delta*se.mult[j]
	   if  (!is.null(P$exclude)) P$ll[P$exclude,j] <- P$ul[P$exclude,j] <- NA
        }
	## for back compatibility...
	P$plot.ci <- P$se
        if (is.null(x$bs)) { P$se.mult <- se.mult;P$se <- se.fit*P$se.mult[1]}  # Note multiplier
      } else P$plot.ci <- FALSE
      P$X <- NULL
      P$plot.me <- TRUE
      pd[[i]] <- P;rm(P) 
    } else { ## P$fit created directly
      if (partial.resids) { P$p.resid <- fv.terms[,length(order)+i] + w.resid }
      P$plot.me <- TRUE
      pd[[i]] <- P;rm(P)
    }
  } ## end of data setup loop through smooths

  
  ##############################################
  ## sort out number of pages and plots per page 
  ##############################################

  n.plots <- n.para
  if (m>0) for (i in 1:m) n.plots <- n.plots + as.numeric(pd[[i]]$plot.me) 

  if (n.plots==0) stop("No terms to plot - nothing for plot.gam() to do.")

  if (pages>n.plots) pages<-n.plots
  if (pages<0) pages<-0
  if (pages!=0)    # figure out how to display things
  { ppp<-n.plots%/%pages
    if (n.plots%%pages!=0) 
    { ppp<-ppp+1
      while (ppp*(pages-1)>=n.plots) pages<-pages-1
    } 

    # now figure out number of rows and columns
    c <- r <- trunc(sqrt(ppp))
    if (c<1) r <- c <- 1
    if (c*r < ppp) c <- c + 1
    if (c*r < ppp) r <- r + 1  
    oldpar<-par(mfrow=c(r,c),mar=c(5,5,3,1))
  
  } else
  { ppp<-1;oldpar<-par()}
  

  #####################################
  ## get a common scale, if required...
  #####################################

  if (scale==-1&&is.null(ylim)) {
    k <- 0
    if (m>0) for (i in 1:m) if (pd[[i]]$plot.me&&pd[[i]]$scale) { ## loop through plot data 
      if (se[1]&&length(pd[[i]]$ll)>1) { ## require CIs on plots
        #ul<-pd[[i]]$fit+pd[[i]]$se
        #ll<-pd[[i]]$fit-pd[[i]]$se
        if (k==0) { 
          ylim <- c(min(pd[[i]]$ll[,1],na.rm=TRUE),max(pd[[i]]$ul[,1],na.rm=TRUE));k <- 1
        } else {
          if (min(pd[[i]]$ll[,1],na.rm=TRUE)<ylim[1]) ylim[1] <- min(pd[[i]]$ll[,1],na.rm=TRUE)
	  if (max(pd[[i]]$ul[,1],na.rm=TRUE)>ylim[2]) ylim[2] <- max(pd[[i]]$ul[,1],na.rm=TRUE)
        }
      } else { ## no confidence limits
        if (k==0) {
          ylim <- range(pd[[i]]$fit,na.rm=TRUE);k <- 1
        } else {
          if (min(pd[[i]]$fit,na.rm=TRUE)<ylim[1]) ylim[1] <- min(pd[[i]]$fit,na.rm=TRUE)
          if (max(pd[[i]]$fit,na.rm=TRUE)>ylim[2]) ylim[2] <- max(pd[[i]]$fit,na.rm=TRUE)
        }
      }
      if (partial.resids) { 
        ul <- max(pd[[i]]$p.resid,na.rm=TRUE)
        if (ul > ylim[2]) ylim[2] <- ul
        ll <-  min(pd[[i]]$p.resid,na.rm=TRUE)
        if (ll < ylim[1]) ylim[1] <- ll
      } ## partial resids done
    } ## loop end 
    ylim <- trans(ylim+shift)
  } ## end of common scale computation
  
  ##############################################################
  ## now plot smooths, by calling plot methods with plot data...
  ##############################################################

  if ((pages==0&&prod(par("mfcol"))<n.plots&&dev.interactive())||
       pages>1&&dev.interactive()) ask <- TRUE else ask <- FALSE 
  
  if (!is.null(select)) {
    ask <- FALSE
  }
 
#  if (ask) { ## asks before plotting
#    oask <- devAskNewPage(TRUE)
#    on.exit(devAskNewPage(oask))
#  }

  if (m>0) for (i in 1:m) if (pd[[i]]$plot.me&&(is.null(select)||i==select)) {
    plot(x$smooth[[i]],P=pd[[i]],partial.resids=partial.resids,rug=rug,se=se,scale=scale,n=n,n2=n2,n3=n3,
                     theta=theta,phi=phi,jit=jit,xlab=xlab,ylab=ylab,main=main,
                     ylim=ylim,xlim=xlim,too.far=too.far,shade.col=shade.col,
                     shift=shift,trans=trans,by.resids=by.resids,scheme=scheme[i],...)
   if (ask) { ## this is within loop so we don't get asked before it's necessary
     oask <- devAskNewPage(TRUE)
     on.exit(devAskNewPage(oask))
     ask <- FALSE ## only need to do this once
   }

  } ## end of smooth plotting loop
  
  ####################################################
  ## Finally deal with any parametric term plotting...
  ####################################################

  if (n.para>0) # plot parameteric terms
  { class(x) <- c("gam","glm","lm") # needed to get termplot to call model.frame.glm 
    if (is.null(select)) {
      attr(x,"para.only") <- TRUE
      termplot(x,se=se,rug=rug,col.se=1,col.term=1,main=attr(x$pterms,"term.labels"),...)
    } else { # figure out which plot is required
      if (select > m) { 
        ## can't figure out how to get this to work with more than first linear predictor
        ## as termplots relies on matching terms to names in original data... 
        select <- select - m # i.e. which parametric term
        term.labels <- attr(x$pterms,"term.labels")
        term.labels <- term.labels[order==1]
        if (select <= length(term.labels)) {
          # if (interactive() && m &&i%%ppp==0) 
          termplot(x,terms=term.labels[select],se=se,rug=rug,col.se=1,col.term=1,...)
        }  
      }
    }
  }
  if (pages>0) par(oldpar)
  invisible(pd)
}`

const rtdal004324Source0020 = "vis.gam <- function(x,view=NULL,cond=list(),n.grid=30,too.far=0,col=NA,color=\"heat\",\n           contour.col=NULL,se=-1,type=\"link\",plot.type=\"persp\",zlim=NULL,nCol=50,lp=1,...)\n# takes a gam object and plots 2D views of it, supply ticktype=\"detailed\" to get proper axis anotation\n# (c) Simon N. Wood 23/2/03\n{ fac.seq<-function(fac,n.grid)\n  # generates a sequence of factor variables of length n.grid\n  { fn<-length(levels(fac));gn<-n.grid;\n    if (fn>gn) mf<-factor(levels(fac))[1:gn]\n    else\n    { ln<-floor(gn/fn) # length of runs               \n      mf<-rep(levels(fac)[fn],gn)\n      mf[1:(ln*fn)]<-rep(levels(fac),rep(ln,fn))\n      mf<-factor(mf,levels=levels(fac))\n    }\n    mf\n  }\n  # end of local functions\n\n  dnm <- names(list(...))\n\n  ## basic issues in the following are that not all objects will have a useful `data'\n  ## component, but they all have a `model' frame. Furthermore, `predict.gam' recognises\n  ## when a model frame has been supplied\n\n  v.names  <- names(x$var.summary) ## names of all variables\n\n  ## Note that in what follows matrices in the parametric part of the model\n  ## require special handling. Matrices arguments to smooths are different\n  ## as they follow the summation convention. \n  if (is.null(view)) # get default view if none supplied\n  { ## need to find first terms that can be plotted against\n    k <- 0;view <- rep(\"\",2) \n    for (i in 1:length(v.names)) {\n      ok <- TRUE\n      if (is.matrix(x$var.summary[[i]])) ok <- FALSE else\n      if (is.factor(x$var.summary[[i]])) {\n        if (length(levels(x$var.summary[[i]]))<=1) ok <- FALSE \n      } else {\n        if (length(unique(x$var.summary[[i]]))==1) ok <- FALSE\n      }\n      if (ok) {\n        k <- k + 1;view[k] <- v.names[i]\n      }\n      if (k==2) break;\n    }\n    if (k<2) stop(\"Model does not seem to have enough terms to do anything useful\")\n  } else { \n    if (sum(view%in%v.names)!=2) stop(gettextf(\"view variables must be one of %s\", \n                                      paste(v.names, collapse = \", \")))\n\n    for (i in 1:2) \n    if  (!inherits(x$var.summary[[view[i]]],c(\"numeric\",\"factor\"))) \n    stop(\"Don't know what to do with parametric terms that are not simple numeric or factor variables\")\n  }\n\n  ok <- TRUE\n  for (i in 1:2) if (is.factor(x$var.summary[[view[i]]])) {\n    if (length(levels(x$var.summary[[view[i]]]))<=1) ok <- FALSE\n  } else {\n    if (length(unique(x$var.summary[[view[i]]]))<=1) ok <- FALSE \n  }\n  if (!ok) stop(gettextf(\"View variables must contain more than one value. view = c(%s,%s).\",\n                view[1], view[2]))\n \n  # now get the values of the variables which are not the arguments of the plotted surface\n\n  # Make dataframe....\n  if (is.factor(x$var.summary[[view[1]]]))\n  m1<-fac.seq(x$var.summary[[view[1]]],n.grid)\n  else { r1<-range(x$var.summary[[view[1]]]);m1<-seq(r1[1],r1[2],length=n.grid)}\n  if (is.factor(x$var.summary[[view[2]]]))\n  m2<-fac.seq(x$var.summary[[view[2]]],n.grid)\n  else { r2<-range(x$var.summary[[view[2]]]);m2<-seq(r2[1],r2[2],length=n.grid)}\n  v1<-rep(m1,n.grid);v2<-rep(m2,rep(n.grid,n.grid))\n  \n  newd <- data.frame(matrix(0,n.grid*n.grid,0)) ## creating prediction data frame full of conditioning values\n  for (i in 1:length(x$var.summary)) { \n    ma <- cond[[v.names[i]]]\n    if (is.null(ma)) { \n      ma <- x$var.summary[[i]]\n      if (is.numeric(ma)) ma <- ma[2] ## extract median\n    }\n    if (is.matrix(x$var.summary[[i]])) newd[[i]] <- matrix(ma,n.grid*n.grid,ncol(x$var.summary[[i]]),byrow=TRUE)\n    else newd[[i]]<-rep(ma,n.grid*n.grid)\n  }\n  names(newd) <- v.names\n  newd[[view[1]]]<-v1\n  newd[[view[2]]]<-v2\n  # call predict.gam to get predictions.....\n  if (type==\"link\") zlab <- paste(\"linear predictor\") ## ignore codetools\n  else if (type==\"response\") zlab <- type\n  else stop(\"type must be \\\"link\\\" or \\\"response\\\"\")\n  fv <- predict.gam(x,newdata=newd,se.fit=TRUE,type=type)\n  z <- fv$fit # store NA free copy now\n  if (is.matrix(z)) {\n    lp <- min(ncol(z),max(1,round(lp)))\n    z <- z[,lp] ## retain selected linear predictor\n    fv$fit <- fv$fit[,lp]\n    fv$se.fit <- fv$se.fit[,lp]\n  }\n  if (too.far>0) { # exclude predictions too far from data\n    ex.tf <- exclude.too.far(v1,v2,x$model[,view[1]],x$model[,view[2]],dist=too.far)\n    fv$se.fit[ex.tf] <- fv$fit[ex.tf] <- NA\n  }\n  # produce a continuous scale in place of any factors\n  if (is.factor(m1)) { \n    m1<-as.numeric(m1);m1<-seq(min(m1)-0.5,max(m1)+0.5,length=n.grid) \n  }\n  if (is.factor(m2)) { \n    m2<-as.numeric(m2);m2<-seq(min(m1)-0.5,max(m2)+0.5,length=n.grid) \n  }\n  if (se<=0) { \n    old.warn<-options(warn=-1)\n    av <- matrix(c(0.5,0.5,rep(0,n.grid-1)),n.grid,n.grid-1)\n    options(old.warn)\n    # z is without any exclusion of gridpoints, so that averaging works nicely\n    max.z <- max(z,na.rm=TRUE)\n    z[is.na(z)] <- max.z*10000 # make sure NA's don't mess it up\n    z <- matrix(z,n.grid,n.grid) # convert to matrix\n    surf.col <- t(av)%*%z%*%av   # average over tiles  \n    surf.col[surf.col>max.z*2] <- NA # restore NA's\n    # use only non-NA data to set colour limits\n    if (!is.null(zlim)) { \n      if (length(zlim)!=2||zlim[1]>=zlim[2]) stop(\"Something wrong with zlim\")\n      min.z <- zlim[1]\n      max.z <- zlim[2]\n    } else { \n      min.z <- min(fv$fit,na.rm=TRUE)\n      max.z <- max(fv$fit,na.rm=TRUE)\n    }\n    if (min.z==max.z) {min.z <- min.z-1;max.z <- max.z + 1}\n    surf.col <- surf.col-min.z\n    surf.col <- surf.col/(max.z-min.z)  \n    surf.col <- round(surf.col*nCol)\n    con.col <- 1\n    if (color==\"heat\") { pal<-heat.colors(nCol);con.col<-4;}\n    else if (color==\"topo\") { pal<-topo.colors(nCol);con.col<-2;}\n    else if (color==\"cm\") { pal<-cm.colors(nCol);con.col<-1;}\n    else if (color==\"terrain\") { pal<-terrain.colors(nCol);con.col<-2;}\n    else if (color==\"gray\"||color==\"bw\") {pal <- gray(seq(0.1,0.9,length=nCol));con.col<-1}\n    else stop(\"color scheme not recognised\")\n    if (is.null(contour.col)) contour.col <- con.col   # default colour scheme\n    surf.col[surf.col<1] <- 1; surf.col[surf.col>nCol] <- nCol # otherwise NA tiles can get e.g. -ve index\n    if (is.na(col)) col <- pal[as.array(surf.col)]\n    z <- matrix(fv$fit,n.grid,n.grid)\n    if (plot.type==\"contour\")\n    { stub <- paste(ifelse(\"xlab\" %in% dnm, \"\" , \",xlab=view[1]\"),\n                    ifelse(\"ylab\" %in% dnm, \"\" , \",ylab=view[2]\"),\n                    ifelse(\"main\" %in% dnm, \"\" , \",main=zlab\"),\",...)\",sep=\"\")\n      if (color!=\"bw\")\n      { txt <- paste(\"image(m1,m2,z,col=pal,zlim=c(min.z,max.z)\",stub,sep=\"\") # assemble image() call\n        eval(parse(text=txt))\n        txt <- paste(\"contour(m1,m2,z,col=contour.col,zlim=c(min.z,max.z)\",\n               ifelse(\"add\" %in% dnm, \"\" , \",add=TRUE\"),\",...)\" , sep=\"\") # assemble contour() call\n         eval(parse(text=txt))       \n      } else\n      { txt <- paste(\"contour(m1,m2,z,col=1,zlim=c(min.z,max.z)\",stub,sep=\"\")  # assemble contour() call\n        eval(parse(text=txt))\n      }\n    } else\n    { stub <- paste(ifelse(\"xlab\" %in% dnm, \"\" , \",xlab=view[1]\"),\n                    ifelse(\"ylab\" %in% dnm, \"\" , \",ylab=view[2]\"),\n                    ifelse(\"zlab\" %in% dnm, \"\" , \",zlab=zlab\"),\",...)\",sep=\"\")\n      if (color==\"bw\")\n      { op <- par(bg=\"white\")\n        txt <- paste(\"persp(m1,m2,z,col=\\\"white\\\",zlim=c(min.z,max.z) \",stub,sep=\"\") # assemble persp() call\n        eval(parse(text=txt))\n        par(op)\n      } else\n      { txt <- paste(\"persp(m1,m2,z,col=col,zlim=c(min.z,max.z)\",stub,sep=\"\")  # assemble persp() call\n        eval(parse(text=txt))\n      }\n    }\n  } else # add standard error surfaces\n  { if (color==\"bw\"||color==\"gray\") \n    { subs <- paste(\"grey are +/-\",se,\"s.e.\")  ## ignore codetools\n      lo.col <- \"gray\" ## ignore codetools claims about this\n      hi.col <- \"gray\" ## ignore codetools \n    } else\n    { subs <- paste(\"red/green are +/-\",se,\"s.e.\")\n      lo.col <- \"green\"\n      hi.col <- \"red\"\n    }\n    if (!is.null(zlim)) {\n      if (length(zlim)!=2||zlim[1]>=zlim[2]) stop(\"Something wrong with zlim\")\n      min.z <- zlim[1]\n      max.z <- zlim[2]\n    } else {\n      max.z <- max(fv$fit+fv$se.fit*se,na.rm=TRUE)\n      min.z <- min(fv$fit-fv$se.fit*se,na.rm=TRUE)\n      zlim<-c(min.z,max.z)\n    } \n    z <- fv$fit - fv$se.fit*se; z <- matrix(z,n.grid,n.grid)\n    if (plot.type==\"contour\") warning(\"sorry no option for contouring with errors: try plot.gam\")\n\n    stub <-  paste(ifelse(\"xlab\" %in% dnm, \"\" , \",xlab=view[1]\"),\n                   ifelse(\"ylab\" %in% dnm, \"\" , \",ylab=view[2]\"),\n                   ifelse(\"zlab\" %in% dnm, \"\" , \",zlab=zlab\"),\n                   ifelse(\"sub\" %in% dnm, \"\" , \",sub=subs\"),\n                   \",...)\",sep=\"\")\n    txt <- paste(\"persp(m1,m2,z,col=col,zlim=zlim\",\n                 ifelse(\"border\" %in% dnm, \"\" ,\",border=lo.col\"),\n                 stub,sep=\"\") # assemble persp() call\n    eval(parse(text=txt))\n\n    par(new=TRUE) # don't clean device\n    z <- fv$fit; z <- matrix(z,n.grid,n.grid)\n\n    txt <- paste(\"persp(m1,m2,z,col=col,zlim=zlim\",\n                 ifelse(\"border\" %in% dnm, \"\" ,\",border=\\\"black\\\"\"),\n                 stub,sep=\"\")\n    eval(parse(text=txt))\n\n    par(new=TRUE) # don't clean device\n    z <- fv$fit+se*fv$se.fit; z <- matrix(z,n.grid,n.grid)\n    \n    txt <- paste(\"persp(m1,m2,z,col=col,zlim=zlim\",\n                 ifelse(\"border\" %in% dnm, \"\" ,\",border=hi.col\"),\n                 stub,sep=\"\")\n    eval(parse(text=txt))\n  }\n}"

